/* 第二十五章 · 绵竹血战 — 逆向自 R_25.EEX */
(function(){
 if(!window.JW_CHAPTERS) window.JW_CHAPTERS=[];
 window.JW_CHAPTERS.push({"id":"ch25","num":25,"title":"第二十五章 · 绵竹血战","desc":"第二十五章 · 绵竹血战（原版剧本 R_25.EEX）","map":"assets/maps/map25.png","intro":{"title":"第二十五章 · 绵竹血战","nodes":[{"type":"scene","bg":"default","name":"邓艾的考量"},{"type":"say","who":"旁白","text":"上邽魏军营帐"},{"type":"say","who":"邓忠","text":"爹，要追击吗？"},{"type":"say","who":"邓艾","text":"忠儿，还在埋怨爹？"},{"type":"say","who":"邓忠","text":"没这回事。"},{"type":"say","who":"邓艾","text":"在战场上和敌人以力相搏的时代已经过去，现在是靠谋略和胆量致胜的时代。"},{"type":"say","who":"邓忠","text":"过去您也是靠著一身武艺得到这个位子，为什么现在会变成这样？"},{"type":"say","who":"邓艾","text":"过去吕布天下无敌，结果如何？关羽威震华夏，结果又如何？"},{"type":"say","who":"邓艾","text":"当看见已故的太傅成功那刻，我终于明白了这些道理。"},{"type":"say","who":"邓忠","text":"………"},{"type":"say","who":"邓艾","text":"以后随著年纪渐长，你会明白的。"},{"type":"say","who":"邓艾","text":"现在号令全军，不要再追击了。"},{"type":"say","who":"郑伦","text":"明明我军打了胜仗，为什么不追了？"},{"type":"say","who":"邓艾","text":"姜维军队还是有相当的战斗能力，万一被他引进熟悉的地形，我们不见得能打赢。"},{"type":"say","who":"邓艾","text":"到时万一被打败，眼前的战功将化为乌有，不如见好就收。"},{"type":"say","who":"邓艾","text":"（更何况我会成为陇西都督，还是因为姜维在这边搞得天翻地覆。留著姜维，我的地位将不可动摇。）"},{"type":"say","who":"邓艾","text":"（只是大将军真的只是因为我可以对付姜维才要我来这边？还是准备用我来逼退陈泰？还是作为切割都督区的试验？）"},{"type":"say","who":"邓艾","text":"（真可怕啊…一个安排背后有那么多考量，这个司马昭一点也不比他父亲逊色。）"},{"type":"say","who":"邓艾","text":"（倒是这次本来应该大胜的战争，被那张嶷搞到惨胜，这家伙快变成挥之不去的梦魇。）"},{"type":"say","who":"邓艾","text":"（从二十多年前，我就在规划偷渡阴平的作战计画，但万一被张嶷埋伏呢？）邓艾因段谷上邽一战的功劳，被擢升为镇西将军，都督陇右诸军事，正式成为曹魏的地方大员。姜维的痛悔姜维军营帐"},{"type":"say","who":"姜维","text":"………"},{"type":"say","who":"宁随","text":"关统将军已经确定战死了，夏侯霸将军也在乱军中下落不明…"},{"type":"say","who":"姜维","text":"我知道！所以我要在这边继续等下去！"},{"type":"say","who":"宁随","text":"夏侯将军生还的机会很低，我们不该浪费宝贵的时间等下去。"},{"type":"say","who":"宁随","text":"应该趁著邓艾还没有追击想法的时候赶快撤退，不然要是我们两军再交战，绝对没有战胜的可能性。"},{"type":"say","who":"姜维","text":"这些我都知道…"},{"type":"say","who":"向充","text":"大将军，该退的时候就要退，我们真的没有本钱再继续打下去了。"},{"type":"say","who":"姜维","text":"因为我的错误判断，一口气让两位大将葬身在战场上…"},{"type":"say","who":"张翼","text":"………"},{"type":"say","who":"柳隐","text":"（张翼今天怎么这么老实，没有说一句话呢？）"},{"type":"say","who":"来忠","text":"（这个罪恶感，压迫得我快喘不过气来，我该怎么办？）"},{"type":"say","who":"张嶷","text":"伯约，这场仗至少还给了敌人相当程度的反击，已经是足够了。"},{"type":"say","who":"张嶷","text":"我想就算是邓艾，短时间内也不至于会入侵大汉。所以，请不要再责备自己。"},{"type":"say","who":"关索","text":"伯约，赶快撤退吧，我可不希望关统的牺牲就这样白费。"},{"type":"say","who":"关索","text":"关于车骑将军的事情，我会负责和星彩说，请不要担心。"},{"type":"say","who":"杨兰","text":"好了！你还继续在这边痛悔也是没用，重要的是要如何收拾残局！"},{"type":"say","who":"杨兰","text":"（我可以预见，站在亲魏立场的姚柯回，势力将会日渐壮大，该怎么办呢？）"},{"type":"say","who":"王嗣","text":"（其实这场仗最大的损失，恐怕是陇西这边，日后难以再获得在地人或是羌人的协助，这点杨姑娘应该也很清楚。）"},{"type":"say","who":"姜维","text":"（一时的失败不算什么，只要还有一口气在，总有一天会再回到这里。）"},{"type":"say","who":"姜维","text":"嗯…全军全速撤回汉中，所有辎重装备，若是不能带走就原地销毁，全军轻装前进，不要拖延到撤退速度。"},{"type":"say","who":"宁随","text":"（好了，接下来就是我的工作…）尹赏之怒成都皇宫"},{"type":"say","who":"谯周","text":"陛下，纵然不想面对也请您面对，这已经是关系到大汉存亡的问题了。"},{"type":"say","who":"谯周","text":"丧师无数，还让虎贲中郎将关统和车骑将军夏侯霸战死沙场，把从丞相以来获得的战果毁于一旦，这都是姜维的错。"},{"type":"say","who":"刘禅","text":"皇后现在情况怎么样了？"},{"type":"say","who":"黄皓","text":"现在情绪已经平稳很多，没有当初听到车骑将军死讯那样激动了。"},{"type":"say","who":"谯周","text":"圣上！"},{"type":"say","who":"董厥","text":"臣也要请陛下三思，一任用姜维这样的外人担任大将军，就出现这样的灾难，再让他当下去，大汉社稷恐怕危险了。"},{"type":"say","who":"郤正","text":"有件事情我很不明白，想要请教二位…"},{"type":"say","who":"郤正","text":"首先是允南（谯周），为什么你只字不提伯约他在逆境中击退邓艾的事情？"},{"type":"say","who":"郤正","text":"纵然我军损失惨重，也算是惨胜，还是足够让曹贼断绝进攻的念头。"},{"type":"say","who":"郤正","text":"有件事情我很不明白，想要请教二位…"},{"type":"say","who":"郤正","text":"首先是允南（谯周），这次纵然是惨败，但是姜维难道是唯一要负责任的人？"},{"type":"say","who":"郤正","text":"请问当时带著大军在汉中附近转圈圈的胡济该如何？"},{"type":"say","who":"郤正","text":"接著是龚袭（董厥），为什么同样是出身自丞相府的你，会特别对伯约有意见？请问他所做的，和丞相做的有什么不同？"},{"type":"say","who":"樊建","text":"（这个郤正平常不太开口，一开口就无比犀利。眼前只有一个人可以压倒他，但那个人靠著是他的家世，不是口才。）"},{"type":"say","who":"樊建","text":"（这个时候我也不知道该怎么办，我对姜维并没有特殊的感情，但之前他涉嫌暗算文伟的事还是让我耿耿于怀。）"},{"type":"say","who":"诸葛瞻","text":"郤正！父亲的作为可以让你随便提出来和姜维类比吗？"},{"type":"say","who":"诸葛瞻","text":"他认可的接班人是蒋公琰和费文伟，绝对不是姜维。"},{"type":"say","who":"诸葛瞻","text":"姜维偷窃我爹辛苦多年的成果，把我爹为大汉苦心存下来的资本投入没有意义的战争中，到最后只换得他的大将军之位。"},{"type":"say","who":"诸葛瞻","text":"这些事情尚书仆射（董厥）他比谁都清楚，正因为他是出身自爹丞相府的官员，他更想维护爹一手撑起来的大汉！"},{"type":"say","who":"郤正","text":"………"},{"type":"say","who":"郤正","text":"（无法反驳啊，在丞相这块神主牌面前，谁都不能多说一句话，哪怕是圣上也不行多说。）"},{"type":"say","who":"刘禅","text":"那么，侍中你要我怎么做？"},{"type":"say","who":"诸葛瞻","text":"罢免姜维，改派值得信任的人接替他担任大将军。"},{"type":"say","who":"刘禅","text":"嗯…这件事情，朕还是想要问一下尚书令的意见。"},{"type":"say","who":"陈祗","text":"这…"},{"type":"say","who":"尹赏","text":"诸葛瞻！你到底知道伯约多少？你什么都不知道就在胡说一气！"},{"type":"say","who":"尹赏","text":"我是在天水时期就认识伯约，他虽然有些任性，而且胆大妄为，但是他对人诚恳，行事光明磊落，绝对是时人的典范。"},{"type":"say","who":"尹赏","text":"许多人污蔑他杀害费祎，我认为这是最恶劣的中伤。"},{"type":"say","who":"尹赏","text":"伯约当时面对恶意陷害他的马遵，他都只有默默承受，何况只是因为政治意见不同而和费祎有争执而已。"},{"type":"say","who":"尹赏","text":"至于说伯约偷窃丞相的成果，那更是可笑无比。"},{"type":"say","who":"尹赏","text":"请问伯约如今的地位，有哪一些不是靠自己打下来的？洮西大捷，纵然是丞相五次北伐也都没有过这样的胜利。"},{"type":"say","who":"樊建","text":"执金吾，你似乎说得有些过火了…"},{"type":"say","who":"尹赏","text":"过火？刚才几位批评伯约的话就不过火，只看见伯约的失败，却忽视伯约对大汉的贡献，以及他为大汉的牺牲。"},{"type":"say","who":"尹赏","text":"他忍受著和亲人分离的孤独，坚持要回报丞相和陛下对他的恩情。"},{"type":"say","who":"尹赏","text":"而如今，丞相的爱子不明白这一切，居然污蔑伯约的赤诚之心，让人听得怎么不怒火中烧。"},{"type":"say","who":"尹赏","text":"你只是一个无用的公子哥，靠丞相的名声在混饭吃，什么都没做，世人就会把功劳归给你！"},{"type":"say","who":"诸葛瞻","text":"你……"},{"type":"say","who":"尹赏","text":"既然你这么行，为什么不亲自领军去对抗邓艾？你行吗？"},{"type":"say","who":"陈祗","text":"执金吾，再怎么体谅你的心情，这样说话都似乎太过分了。"},{"type":"say","who":"陈祗","text":"你口出恶言，侮辱到丞相之子甚至是丞相，这已经是很严重的罪行。"},{"type":"say","who":"尹赏","text":"哈哈哈，我尹赏窝囊了一辈子，今天总算想通了，不想再受这样的鸟气。"},{"type":"say","who":"尹赏","text":"我为什么要怕你或是诸葛瞻这种鸟官？"},{"type":"say","who":"尹赏","text":"只会用嘴巴获得高位的人，和伯约根本就不能比。让你们这些废物当政，真是大汉的不幸！"},{"type":"say","who":"尹赏","text":"（对不起，我只能陪你到这里了…伯约，到那边，我会和小妹一起庇佑你的。）"},{"type":"say","who":"董厥","text":"这个尹赏简直是造反了！来人！来人！"},{"type":"say","who":"郤正","text":"等一下，执金吾情况似乎不对！"},{"type":"say","who":"尹赏","text":"………"},{"type":"say","who":"诸葛瞻","text":"他死了？"},{"type":"say","who":"谯周","text":"慷慨激昂，直立而逝，纵然立场不相同，但是精神让人感佩不已。"},{"type":"say","who":"刘禅","text":"……即刻安葬他…"},{"type":"say","who":"陈祗","text":"（尹赏啊，说得很完美，在场所有人都被你压倒了。）"},{"type":"say","who":"陈祗","text":"（如果不是你，恐怕我也得跳下去对姜维发动攻击。只是，为什么你要为他做到这种地步？只为了虚幻的友情？）来敏的悔恨成都来府"},{"type":"say","who":"来敏","text":"忠儿，你回来了…咳咳咳咳…"},{"type":"say","who":"来忠","text":"爹，您憔悴了许多。"},{"type":"say","who":"来敏","text":"老夫接到前线的战报时，差点以为你也遇难，那段期间可真是折腾死老夫了。"},{"type":"say","who":"来忠","text":"爹，我们犯下的，可是滔天大罪呀。"},{"type":"say","who":"来忠","text":"长久以来，我们认为自己是边缘人，所以处在危险的状态下，必须用尽心力来自保，否则就有灭亡的危机。"},{"type":"say","who":"来忠","text":"但是，事实真的如此？刘敏将军暗示我的话，我到了最近才开始明白，并非所有人都对我们有敌意。"},{"type":"say","who":"来忠","text":"大将军对我也推心置腹，这次的事情很明显是我们造成的，但他却没有过问我一句，还帮我挡住责难。"},{"type":"say","who":"来忠","text":"爹您想想，过去您做的这一切，到底是谁得利？不断地挑拨，制造纷争，到最后是谁爬到高位？"},{"type":"say","who":"来敏","text":"陈祗…老夫真是太低估他了，以为他只是个后生晚辈，哪知道他一瞬间就爬到这么高的位子。"},{"type":"say","who":"来敏","text":"他都躲在后面，让老夫去和姜维对立，自己一方面在姜维面前装作是姜维的协力者。"},{"type":"say","who":"来敏","text":"他面面俱到，整个朝中根本就没有人是他的敌人。更重要的是，连圣上都信任他。"},{"type":"say","who":"来忠","text":"既然您已经知道这点，就此罢手好吗？我也打算向大将军请罪，任他处置，只希望他能阻止常败军的人向您报复。"},{"type":"say","who":"来敏","text":"你说这什么话，老夫是行将就木的老人，哪怕什么报复！反而是你还年轻，怎么可以就这样葬送自己。"},{"type":"say","who":"来忠","text":"我造的孽实在太多了，段谷之战中每个丧命的弟兄，实际上都是我杀的…"},{"type":"say","who":"来敏","text":"不，其实是老夫造的孽，你不需要帮老夫去背负。"},{"type":"say","who":"来忠","text":"爹，就让我去面对吧，否则您要孩儿在接下来的人生都抬不起头来？"},{"type":"say","who":"来敏","text":"这…战争的代价成都车骑将军府"},{"type":"say","who":"关索","text":"我就知道你会在这里…"},{"type":"say","who":"张皇后","text":"如果不透过收拾夏侯将军的遗物来整理心情的话，现在的我，恐怕会开始怨恨别人吧。"},{"type":"say","who":"关索","text":"这件事情不是任何人的错，只要是战争就会带来这样的结果。"},{"type":"say","who":"张皇后","text":"我知道…不过当年我爹也没听进去这样的话，不是吗？"},{"type":"say","who":"关索","text":"我们关家最年轻一代的希望，在这场战争瞬息消失，其实我也不知道要怎么向去世的二哥交代。"},{"type":"say","who":"张皇后","text":"那么你就不怨恨姜维？"},{"type":"say","who":"关索","text":"不，事前看见关统那样浮躁的表现，却仍然没有阻止，责任都在我。"},{"type":"say","who":"张皇后","text":"你可真会把责任往自己身上揽。"},{"type":"say","who":"花鬘","text":"够了！不要再对关索冷嘲热讽的啦！"},{"type":"say","who":"张皇后","text":"记得你是…孟获的女儿？"},{"type":"say","who":"花鬘","text":"没错！我本来以为张飞的女儿有多了不起，哪知道只是个会耍脾气，一身公主病的笨女人而已的啦。"},{"type":"say","who":"张皇后","text":"………"},{"type":"say","who":"花鬘","text":"说不出话来？你想说什么就该大声说，装什么端庄？我呸！还皇后呢！"},{"type":"say","who":"关索","text":"花鬘！不要…"},{"type":"say","who":"花鬘","text":"怕我骂哭你的星彩？"},{"type":"say","who":"关索","text":"不是这样的…"},{"type":"say","who":"张皇后","text":"够了！老娘我已经够不爽了，你他妈还在那说什么鬼？"},{"type":"say","who":"张皇后","text":"你是老鼠眼、鹰勾鼻、八字眉、招风耳、大翻嘴、黄板牙、鸡脖子、烂脖子、长短手、大小手、鸡胸、狗肚、饭桶腰。"},{"type":"say","who":"张皇后","text":"你说你这个样子还是个人吗？我要是你呀，早就上吊自尽啦！"},{"type":"say","who":"花鬘","text":"你…你敢骂我？小心不得好死！"},{"type":"say","who":"张皇后","text":"我死了也要拉你当垫背的！"},{"type":"say","who":"花鬘","text":"小心生儿子没屁眼！"},{"type":"say","who":"张皇后","text":"没屁眼的儿子是你生的！"},{"type":"say","who":"花鬘","text":"我看你能凶多久！"},{"type":"say","who":"张皇后","text":"凶到你嗝屁为止！"},{"type":"say","who":"张皇后","text":"你不化妆比化妆美，做鬼比做人好。我做人气得你发昏，做鬼吓跑你的魂。"},{"type":"say","who":"花鬘","text":"呜哇！（这女人吵架功力，真是不同凡响！）"},{"type":"say","who":"关索","text":"我就说不要刺激她，她老爹张飞过去可是在瓦口关把张郃骂到吐血的。"},{"type":"say","who":"张皇后","text":"呼…清爽多了，似乎我得感谢你和旁边那个笨女人。"},{"type":"say","who":"花鬘","text":"呜呜呜…"},{"type":"say","who":"关索","text":"只希望你不要就此怨恨姜维才好，否则夏侯将军恐怕也无法安息的。"},{"type":"say","who":"张皇后","text":"我知道，说不定对他来说，也希望战死沙场，而非就这样客死异乡吧。"},{"type":"say","who":"张皇后","text":"（我总感觉，夏侯将军还活著，他不是个这么容易死的人。）奇迹的生还谧友堂"},{"type":"say","who":"夏侯和","text":"二哥，果然是您！"},{"type":"say","who":"夏侯霸","text":"这里是哪里？"},{"type":"say","who":"夏侯和","text":"这里是神医皇甫谧的诊所，您中了好几箭，幸亏您得到他的医治，否则您早就已经不行了。"},{"type":"say","who":"皇甫谧","text":"别太看得起我，比起闻名天下的华陀，我可是差了一大截。"},{"type":"say","who":"皇甫谧","text":"你能得救是因为这副铠甲，不然这箭再深几吋我也束手无策了。"},{"type":"say","who":"夏侯霸","text":"果然这是父亲在天之灵的保佑。"},{"type":"say","who":"皇甫谧","text":"好了，既然夏侯将军脱离险境，就让你们兄弟好好相处吧。"},{"type":"say","who":"夏侯霸","text":"我该怎么感谢你？至少诊疗费该收一点吧。"},{"type":"say","who":"皇甫谧","text":"不用谢我，医生治疗人是天职。"},{"type":"say","who":"皇甫谧","text":"更何况我们“谧友堂”从来不收诊疗费的。"},{"type":"say","who":"夏侯和","text":"大夫，还是感谢您的救助！"},{"type":"say","who":"夏侯霸","text":"救命之恩，没齿难忘。"},{"type":"say","who":"皇甫谧","text":"请夏侯将军记住一件事，在这里活著就表示上天有另外的安排。"},{"type":"say","who":"皇甫谧","text":"找到自己的目标，完成自己的天命是您崭新人生接下来该做的事情。"},{"type":"say","who":"夏侯霸","text":"七弟，这几年你过得还好吗？其他两个弟弟怎么样了？"},{"type":"say","who":"夏侯和","text":"六哥（夏侯惠）从辽东回来不久就去世，四哥（夏侯威）也在不久前病逝了，整个家就只剩下我一个人。"},{"type":"say","who":"夏侯霸","text":"司马家没有迫害你吧？你现在还好？"},{"type":"say","who":"夏侯和","text":"靠著侄女的关系，我和泰山羊家搭上线，司马家也就没有为难我。"},{"type":"say","who":"夏侯霸","text":"原来如此，看来我的女婿羊叔子还有些办法。"},{"type":"say","who":"夏侯和","text":"只是…因为有太初的那件事情发生，我被迫要对司马家卑躬屈膝，现在是司马昭大将军府的属官。"},{"type":"say","who":"夏侯霸","text":"七弟，过去我怎么对你说的？"},{"type":"say","who":"夏侯和","text":"二哥，我真的身不由己！"},{"type":"say","who":"夏侯霸","text":"那么…你是来捉拿我的？"},{"type":"say","who":"夏侯和","text":"怎么可能！我本来就在这附近要代表司马昭慰劳邓艾。"},{"type":"say","who":"夏侯和","text":"我一听说您阵亡的消息就急忙赶到这附近要安葬您，没想到居然给我遇上了这样的奇迹。"},{"type":"say","who":"夏侯和","text":"二哥，虽然我很没用，但是绝对不会出卖自己的亲人，请您一定要相信我！"},{"type":"say","who":"夏侯和","text":"我拚著这条命，也要保护您的安全。"},{"type":"say","who":"夏侯霸","text":"对不起，我错怪你了。"},{"type":"say","who":"夏侯霸","text":"其实我根本没有理由说你，我自己不也是很自私地投奔蜀地，把你们害得这么惨。"},{"type":"say","who":"夏侯和","text":"这样的选择是最好的，若是您还留在这边，恐怕就像太初那样被杀了。"},{"type":"say","who":"夏侯霸","text":"我在那边虽然有些寂寞，但却有亲人相伴，想想我比你们幸福太多。"},{"type":"say","who":"夏侯和","text":"亲人？"},{"type":"say","who":"夏侯霸","text":"张飞的女儿，她是当年被掳去的那个从妹生下的孩子。"},{"type":"say","who":"夏侯和","text":"哦？！这世界还真是小！"},{"type":"say","who":"夏侯和","text":"二哥，请您要好好静养，等待时机。"},{"type":"say","who":"夏侯霸","text":"嗯…我知道了。"},{"type":"say","who":"夏侯和","text":"似乎蜀人把二哥您也变圆滑了，这样的转变并不是什么坏事。最大的战争姜维军军营"},{"type":"say","who":"宁随","text":"这边的事情就交给你了，我现在就要启程到成都那边去。"},{"type":"say","who":"向充","text":"老师，这次真的是辛苦您了，可惜常败军的人都不知道老师您真正的贡献。"},{"type":"say","who":"宁随","text":"我本来就在战场上发挥不了太大的作用，更何况像我这种本来早就该死的人，哪里还需要让人家知道呢？"},{"type":"say","who":"向充","text":"老师您这次的策略实在是很冒险，到底有几成把握可以说服对方呢？"},{"type":"say","who":"宁随","text":"百分之百的把握。"},{"type":"say","who":"宁随","text":"现在整个情势完全转变，本来是敌人的要拉拢，本来是我方的变成敌人，这点对方也知道。"},{"type":"say","who":"向充","text":"我也没有想到，一向成为我们后盾的人们居然倒戈。而益州人早在之前就不支持我们。"},{"type":"say","who":"宁随","text":"从公琰去世，许多老将凋零之后，我们的后盾就变得越来越弱。"},{"type":"say","who":"宁随","text":"幸好来家父子已经被我们拉拢到，我要更进一步去拉拢这些刘璋旧部的非益州人来保护常败军。"},{"type":"say","who":"向充","text":"郤正本来就对我们很友善，剩下果然就是那个人了…"},{"type":"say","who":"向充","text":"只是，我还是很想问老师这个问题，明明如同廖立说的，让大将军掌控朝政，消除一切杂音就好了，为何老师不那样做？"},{"type":"say","who":"宁随","text":"你认为我会愿意去制造一个董卓或曹操？"},{"type":"say","who":"向充","text":"老师！大将军不可能变成这两个恶棍的！"},{"type":"say","who":"宁随","text":"这两个人也不是生下来就是恶棍，希望你能够明白这点。"},{"type":"say","who":"向充","text":"可是丞相他也…"},{"type":"say","who":"宁随","text":"住口！没有人可以和丞相相比，没有人可以…再次交易成都郊外"},{"type":"say","who":"陈祗","text":"这次找我做什么？本来我应该下定决心要和你们切断关系的。"},{"type":"say","who":"宁随","text":"首先我得先感谢你，若不是你之前手下留情，伯约大概早就被拔掉大将军之位。"},{"type":"say","who":"陈祗","text":"那天若不是尹赏宁可一死，也要慷慨直言，姜维的命运早就已经决定了。"},{"type":"say","who":"陈祗","text":"只是你认为他还能保住大将军的位子？"},{"type":"say","who":"宁随","text":"不，绝对不可能。"},{"type":"say","who":"宁随","text":"不过，有件事情要请你考虑的，伯约之后，又有谁可以掌兵？"},{"type":"say","who":"宁随","text":"自从两位吴将军病逝之后，你们这边就再也没有可以统兵的人才了。"},{"type":"say","who":"宁随","text":"相对来说，荆州人那边或许还有阎宇和胡济这两个人可以接替。"},{"type":"say","who":"宁随","text":"只是你愿意让诸葛瞻和董厥这两人的权力越来越大？"},{"type":"say","who":"宁随","text":"董厥先不说，诸葛瞻这样亮眼的政治明星应该也给你很大的压力吧。"},{"type":"say","who":"宁随","text":"朝廷一有好的政策，人民就会自动通告说这都是诸葛瞻之所为，试问我们大汉除了丞相外，谁有这样的名声？"},{"type":"say","who":"宁随","text":"你可以轻易拔除庞统的儿子，但是面对诸葛瞻，你可完全没有下手的空间。"},{"type":"say","who":"陈祗","text":"被你说中了…诸葛瞻真是个麻烦人物，但是我也没有这个能力打压他，最多只能守住自己的位子，避免他往上爬。"},{"type":"say","who":"陈祗","text":"老实说，我一来不希望把兵权送给你们荆州人，二来，我也不认为有人会比姜维更能对抗曹贼。"},{"type":"say","who":"宁随","text":"我可以保证，伯约只要军权，政权交给你，就像是之前那样的模式。"},{"type":"say","who":"陈祗","text":"维持现状是我的期望，也是圣上的期望，这点你要记清楚。"},{"type":"say","who":"宁随","text":"当然，也请你要知道，现在的常败军状况非常危险。我们不会放过任何一根可以抓的稻草。"},{"type":"say","who":"陈祗","text":"既然这样，我就愿意当那稻草。"},{"type":"say","who":"宁随","text":"我就代伯约表示感谢之意。"},{"type":"say","who":"陈祗","text":"其实还真妙呀，世人都认为姜维和我互通声息，却不知道我和他几乎没有见过几次面。"},{"type":"say","who":"宁随","text":"我也很好奇，为什么你会看中伯约？"},{"type":"say","who":"陈祗","text":"真要说的话，或许是因为他的孤独处境和我很像。怎么样？不像是我这种利欲薰心的人会说的话？"},{"type":"say","who":"宁随","text":"不，我相信。"},{"type":"say","who":"陈祗","text":"嗯…听说姜维也快到成都了，希望这几天能看见他亲自进宫面圣。杨兰的安慰成都郊外"},{"type":"say","who":"姜维","text":"你知道吗？尹兄是我数十年的好盟友，虽然他很懦弱，但是他还是会试著鼓起勇气去做任何事情。"},{"type":"say","who":"姜维","text":"只是我没有想到，这次他居然有著我完全无法比拟的勇气，敢在所有重臣和圣上前面激昂陈辞。"},{"type":"say","who":"姜维","text":"据说连丞相公子都被他骂到哑口无言。"},{"type":"say","who":"姜维","text":"我到底做了什么事情？我打了这样难看的战争，害死了夏侯将军和关将军，现在甚至连尹兄都被我害死。"},{"type":"say","who":"杨兰","text":"乖…乖…想哭就哭，想找人撒娇就找我。别开玩笑了！………"},{"type":"say","who":"姜维","text":"别开玩笑了，我没有这种心情。"},{"type":"say","who":"杨兰","text":"我什么时候在你面前开过玩笑？"},{"type":"say","who":"杨兰","text":"别把自己看这么伟大，这种败仗可不是你一个人的力量可以承担的。"},{"type":"say","who":"杨兰","text":"遗族的怨恨、同僚的嘲讽马上就会排山倒海而来，真正的战争才要开始。"},{"type":"say","who":"杨兰","text":"我杨兰不能帮你别的，但至少可以让你在面对责难时，知道自己不是一个人。"},{"type":"say","who":"杨兰","text":"要是我连这点都做不到，就完全辜负当初尹赏的托付了。"},{"type":"say","who":"姜维","text":"（咦？刚才有这么一瞬间，我还真把她看成香了。）"},{"type":"say","who":"杨兰","text":"别把自己看这么伟大，这种败仗可不是你一个人的力量可以承担的。"},{"type":"say","who":"杨兰","text":"遗族的怨恨、同僚的嘲讽马上就会排山倒海而来，真正的战争才要开始。"},{"type":"say","who":"杨兰","text":"我杨兰不能帮你别的，但至少可以让你在面对责难时，知道自己不是一个人。"},{"type":"say","who":"杨兰","text":"要是我连这点都做不到，就完全辜负当初尹赏的托付了。"},{"type":"say","who":"姜维","text":"（咦？刚才有这么一瞬间，我还真把她看成香了。）"},{"type":"say","who":"杨兰","text":"你这次居然故意不在汉中停留，彷彿在逃避诸葛果一样。"},{"type":"say","who":"姜维","text":"……你生气吗？"},{"type":"say","who":"杨兰","text":"我当然会生气，你平常这么依赖她，这时候却又把她丢到一边去。"},{"type":"say","who":"杨兰","text":"不过呢，这次就原谅你吧，我知道你有你的苦衷。"},{"type":"say","who":"姜维","text":"我已经做了个决定，我想在明天面圣的时候，亲自面对所有的责难，并且辞掉大将军的职位。"},{"type":"say","who":"杨兰","text":"无所谓，你做什么我都挺你，反正你就算不是大将军，还是可以打仗的。"},{"type":"say","who":"姜维","text":"我实在是受你太多照顾了。"},{"type":"say","who":"杨兰","text":"呵呵呵，再多夸赞我一点。蜀人的怨恨成都大街"},{"type":"say","who":"男子","text":"姜维！你他妈给我去死啦！"},{"type":"say","who":"农夫","text":"烂人，你还有脸回来！我的两个儿子都死在这场大败中。"},{"type":"say","who":"老妇","text":"呜呜呜，你还我儿子啊，我儿子不是说跟著姜维出征就不会死，怎么会这样？"},{"type":"say","who":"姜维","text":"………"},{"type":"say","who":"杨兰","text":"你们别太过分！连鸡蛋都丢过来是怎样！"},{"type":"say","who":"姜维","text":"杨兰，不要这样，他们都是这场大败的受害者，被骂还只是小事而已。"},{"type":"say","who":"杨兰","text":"这些人真是无理取闹…过去是你是怎么样为这个国家奋斗，他们都没看见吗？"},{"type":"say","who":"姜维","text":"我这点确实远远比不过丞相。"},{"type":"say","who":"姜维","text":"丞相在北伐失败后，可以马上收拾起一切，让人民忘记败战的苦痛，但我却没能力做到。"},{"type":"say","who":"杨兰","text":"丞相是丞相，你是你，这点请你也不要忘记了。"},{"type":"say","who":"旁白","text":"▶ 是呀…"},{"type":"say","who":"杨兰","text":"真讨厌耶！那鸡蛋真的超难洗的！最终的处置成都皇宫"},{"type":"say","who":"刘禅","text":"关于执金吾的事情，朕感到万分遗憾。"},{"type":"say","who":"姜维","text":"微臣认为尹兄并无遗憾，他能够在一生的最后一刻克服他心中的恐惧，已经不会有遗憾了。"},{"type":"say","who":"董厥","text":"所谓的满足，就是在朝堂之上大呼小叫？"},{"type":"say","who":"刘禅","text":"执金吾的事情，朕都已经原谅他了，难道尚书仆射你还要耿耿于怀？"},{"type":"say","who":"董厥","text":"臣不敢…"},{"type":"say","who":"刘禅","text":"朕听说这次会损失如此惨重，和镇西大将军行军延滞有关，所以特地找他来和大将军对质。"},{"type":"say","who":"胡济","text":"臣…"},{"type":"say","who":"姜维","text":"没有这回事，所有的责任都在微臣。"},{"type":"say","who":"姜维","text":"是微臣不见好就收，深入敌阵多时，造成补给困难，最后才害我军有这样下场。"},{"type":"say","who":"胡济","text":"（伯约，这次我真的对不起你。）"},{"type":"say","who":"陈祗","text":"（这个姜维也真是的，明明圣上就已经有意要维护他，现在他却自愿放弃。）"},{"type":"say","who":"陈祗","text":"（不过若是姜维把所有责任都推给胡济，恐怕他也会和荆襄人正式决裂，到时候他也没多好过。）"},{"type":"say","who":"姜维","text":"（我心中还是有怨恨，但至少胡济他还是经历过丞相北伐的世代。若换成其他人，难说会不会支持再度用兵。）"},{"type":"say","who":"陈祗","text":"臣以为，大将军这次虽然造成我军重大损失，但也给敌人相当的打击，若说有过错，也不至于太严重。"},{"type":"say","who":"陈祗","text":"因为这样的小过就处置我国军事的栋梁，这样不是称了贼营的心？"},{"type":"say","who":"陈祗","text":"这次大将军虽然大败，但自古以来名将何人没有遭逢败绩？纵是丞相也有街亭一败。"},{"type":"say","who":"陈祗","text":"因段谷一败就忘记洮西大捷，这实在不是我们应该对待大将军这样人才的态度。"},{"type":"say","who":"谯周","text":"（陈祗这家伙！只要他在一天，陛下就会继续被蒙蔽去支持姜维。）"},{"type":"say","who":"诸葛瞻","text":"（陈祗这个家伙，居然和姜维狼狈为奸，有这两人把持朝政，爹苦心经营的大汉政风将毁于一旦。）"},{"type":"say","who":"诸葛瞻","text":"（费叔叔一时看走眼，让这样的奸人当道。我真恨自己现在没有更大的权力，不然我一定会立刻为国除奸。）"},{"type":"say","who":"姜维","text":"陛下，微臣希望自贬三等，来表示对这件事负责。"},{"type":"say","who":"董厥","text":"哼，连这点都和丞相学，有点创意好吗？"},{"type":"say","who":"刘禅","text":"好吧。"},{"type":"say","who":"刘禅","text":"姜维出师不利，在段谷一战丧师辱国，即刻贬为后将军。"},{"type":"say","who":"诸葛瞻","text":"（好呀，终于把这个穷兵黩武的疯子赶下来了。）"},{"type":"say","who":"刘禅","text":"但朕仍认为姜维为国家不可或缺的栋梁，所以命其以后将军行大将军事。"},{"type":"say","who":"姜维","text":"陛下…"},{"type":"say","who":"刘禅","text":"朕相信你，就像过去相信相父那样。"},{"type":"say","who":"姜维","text":"臣一定为大汉誓死效忠！"},{"type":"say","who":"诸葛瞻","text":"……坦诚相见成都尚书令府"},{"type":"say","who":"陈祗","text":"老实对你说，胡济的援军是我按下来的，目的是希望让你打败仗，压制你的气焰。"},{"type":"say","who":"姜维","text":"我大概也猜到了，只差向来忠证实而已。"},{"type":"say","who":"陈祗","text":"感觉我很恐怖？为了巩固自己的地位，让上千的大汉将士送命都在所不惜。"},{"type":"say","who":"姜维","text":"我确实很愤怒，但是我却没有资格怪你。是我自己不识敌情，冒著断粮危险驻屯于敌境。"},{"type":"say","who":"陈祗","text":"嗯…你真是个让人捉摸不定的人…"},{"type":"say","who":"陈祗","text":"我已经在你的面前表现出我的本性，一个贪婪又自私，可以为了自己的私利牺牲掉任何人。"},{"type":"say","who":"陈祗","text":"但是你呢？你究竟是什么样的人？"},{"type":"say","who":"陈祗","text":"你执意要率军北伐究竟是为何？为了丞相的知遇之恩？还是个人的名利？"},{"type":"say","who":"姜维","text":"都是也都不是。"},{"type":"say","who":"姜维","text":"我并非完全无私之完人，一样希望能够升官晋爵。"},{"type":"say","who":"姜维","text":"只要北伐大业能完成，既可实现丞相的梦想，回报丞相恩情，也可使自己功成名就，我认为这些没有冲突。"},{"type":"say","who":"陈祗","text":"嗯…果然我还是搞不懂你。"},{"type":"say","who":"陈祗","text":"不过，比起其他有太多背景的将领，我还是想要和你合作。"},{"type":"say","who":"陈祗","text":"你没有拒绝的权力，在现在的情况下，和我合作是你生存的唯一之途。"},{"type":"say","who":"陈祗","text":"你鄙视我也好，怨恨我也好，要成就大事你就得忍耐。"},{"type":"say","who":"陈祗","text":"你习惯和君子相处，也得学会和小人共事，这是我给你的最好建议。"},{"type":"say","who":"姜维","text":"我明白了。"},{"type":"say","who":"陈祗","text":"毫不犹豫就答应？你该知道我是声名狼藉的小人吧。"},{"type":"say","who":"姜维","text":"就算如此，我还是看见你充满算计的外表下，有个想要做一番事业的心。"},{"type":"say","who":"陈祗","text":"真可笑，像我这种和黄皓互为表里的小人会有什么大志？"},{"type":"say","who":"姜维","text":"你的外祖父许司徒名满天下，就连丞相见了他都要下拜。"},{"type":"say","who":"姜维","text":"身为外孙的你没有道理不想效法他，成为天下传颂的名士。"},{"type":"say","who":"陈祗","text":"你知道那样的名士曾经被先帝鄙视？他在曾经对他有恩的刘璋困顿时，居然第一个逃跑。"},{"type":"say","who":"陈祗","text":"先帝重用他不过是认为他有名声罢了。"},{"type":"say","who":"姜维","text":"我不这么认为，如果许司徒真的空有名声，那么先帝不会在即位之时还让他担任大汉建国以来唯一的三公。"},{"type":"say","who":"姜维","text":"他用自己的行动来洗刷污名，用更积极的表现证明自己非虚有其表。"},{"type":"say","who":"姜维","text":"纵然一时失足，然不能掩饰司徒是大汉第一名士的光彩。"},{"type":"say","who":"陈祗","text":"回到前线去吧，那里才是你该奋斗的地方，后方的战斗自有人在负责。"},{"type":"say","who":"姜维","text":"（其实奉宗说的也没有错呀，我把政治这件事情看简单了。没有他在成都的运作，只怕我早就被陛下舍弃。）"},{"type":"say","who":"姜维","text":"（不过纵然如此，我还是不想要跨越那条线，当一个人手握军政大权，就只能走上不归路了。）"},{"type":"say","who":"陈祗","text":"（我现在明白为什么丞相会对这个外人这么另眼相看，他心中总是有些与众不同的观点。）"},{"type":"say","who":"陈祗","text":"（我纵然得到陛下的信任，但还是不足以像丞相那样只手遮天。所以我必须要外联姜维，内结黄皓。）"},{"type":"say","who":"陈祗","text":"（其实默许这样政体运作的，不就是陛下吗？外人看我操弄权势，其实我是投陛下所好，让他能够放心。）"},{"type":"say","who":"陈祗","text":"（我们都是陛下手上的玩物，但是不想当玩物就得成为司马懿或孙峻，难道就没有解决之道？）诸葛果的行动汉中诸葛家"},{"type":"say","who":"赵统","text":"不知道诸葛姑娘找我们兄弟俩有什么事情？"},{"type":"say","who":"诸葛果","text":"我想要去寿春一趟，需要两位的同行。"},{"type":"say","who":"赵统","text":"什么？！寿春？"},{"type":"say","who":"赵广","text":"（诸葛姑娘开口永远是让人惊奇。）"},{"type":"say","who":"诸葛果","text":"原因到时候再说，两位可否答应同行？"},{"type":"say","who":"赵统","text":"我想要知道原因！"},{"type":"say","who":"赵广","text":"我倒认为诸葛姑娘这样说，一定有她的用意在，不如答应吧。"},{"type":"say","who":"赵统","text":"不行，这次我一定要听到理由！"},{"type":"say","who":"赵广","text":"（大哥的固执脾气，真是像透了爹。）"},{"type":"say","who":"黄月英","text":"我的女儿有话经常都不说，就由我来说吧。"},{"type":"say","who":"黄月英","text":"我们诸葛家有个亲戚人在寿春，女儿想要去拜访他而已。"},{"type":"say","who":"赵统","text":"亲戚？"},{"type":"say","who":"赵广","text":"我好像有听过一个叫做诸葛诞的…"},{"type":"say","who":"黄月英","text":"小赵将军果然聪明，确实就是要去拜访他。"},{"type":"say","who":"诸葛果","text":"娘，不阻止我？"},{"type":"say","who":"黄月英","text":"如果我阻止你，你心中的罪恶感永远不会消除，这样反而是害了你。"},{"type":"say","who":"黄月英","text":"只是，我从来没有听孔明说过关于他那位族弟的事情，你对于他了解多少？"},{"type":"say","who":"诸葛果","text":"根据杨姑娘从毌丘俭等人口中听来的说法，我大概可以知道他是什么样的人。"},{"type":"say","who":"黄月英","text":"为了大汉或是姜维，你真的已经下定决心要做这种事？你有背负诸葛诞性命的觉悟了吗？"},{"type":"say","who":"诸葛果","text":"父亲说过，人一生只能杀一个人…我已经有觉悟了…"},{"type":"say","who":"黄月英","text":"好！过去我也曾经为孔明背负过一条人命，或许这就是诸葛家的宿命吧。"},{"type":"say","who":"黄月英","text":"那么两位赵将军，愿意陪小女去吗？"},{"type":"say","who":"赵统","text":"我听傅佥说过，贼营那边有许多非常厉害的高手，我也想见识一下。"},{"type":"say","who":"赵广","text":"我从来没有踏上过贼营的领土，这次能够增广见闻也是好事。"},{"type":"say","who":"黄月英","text":"那么就有劳二位了。文钦的壮志河边"},{"type":"say","who":"文钦","text":"我们来到这里有多久了？"},{"type":"say","who":"文虎","text":"大概有一年了吧。"},{"type":"say","who":"文钦","text":"才一年？对我来说像过了十年一样。"},{"type":"say","who":"文钦","text":"四十年前，因为魏讽案牵连，若不是武帝看我是功臣之子赦免我，我早就没命。"},{"type":"say","who":"文钦","text":"我这条命是武帝给的。除了报答昭伯、仲恭的知遇之恩，我所做的一切，更是为了回报武皇帝当年的恩情！"},{"type":"say","who":"文钦","text":"这一年来，想到仲恭对我说过的话，我就恨不得马上回去和司马家拚个你死我活。"},{"type":"say","who":"文虎","text":"爹，孩儿实在是感佩您重情义的表现。"},{"type":"say","who":"文鸯","text":"爹，您在这边也该注意到一些事情吧。"},{"type":"say","who":"文鸯","text":"这边的政治斗争激烈程度，丝毫不输过去的大魏。"},{"type":"say","who":"文鸯","text":"目前我们很得孙峻信任，但是万一他倒下来呢？这里政变频繁，什么事情都会发生的。"},{"type":"say","who":"文钦","text":"所以我才请求孙峻发兵北伐，我想趁著他还当权的时候，尽快了却我的心愿。"},{"type":"say","who":"文鸯","text":"说得也是，他有著不得不答应的理由。"},{"type":"say","who":"文钦","text":"他现在的权力基础很薄弱，只不过是靠著和全家的结合，勉强取得优势，然而他没有本事完全排除其他有力人士。"},{"type":"say","who":"文钦","text":"只有靠著建立自己的战功，才能够让自己的权力正当化，也才能堵住其他人的嘴。"},{"type":"say","who":"文虎","text":"父亲真是见多识广。"},{"type":"say","who":"文鸯","text":"想不到我们来到这边以后，反而更难在战场上放手一搏。"},{"type":"say","who":"文钦","text":"阿鸯，我也不希望变成这样。"},{"type":"say","who":"文钦","text":"当初我也瞧不起那些看当权者脸色吃饭的将领，结果我在这边也变成这样的人。"},{"type":"say","who":"文钦","text":"这样的环境实在是不能久留，纵然我们获得高官显爵，终究会腐蚀我们的内心。"},{"type":"say","who":"文鸯","text":"那么等到北伐的时候再杀个痛快就好了，这次我可不会放过小昭昭。"},{"type":"say","who":"文钦","text":"有这样的志气，真不愧是我文钦的儿子。东吴镇北大将军文钦，向丞相孙峻分析攻打曹魏的好处，终于获得出兵的许可。文钦和骠骑将军吕据、车骑将军刘纂、镇南将军朱异、前将军唐咨等，从江都进入淮泗一带，准备攻击曹魏的青州和徐州地区。然而，文钦的北伐美梦，却在孙峻得到急病后，出现了重大变数…私相授受石头城临时丞相府"},{"type":"say","who":"孙綝","text":"听到您急急忙忙召我过来，我大概就知道发生什么事情了，只是没想到事情会这么严重。"},{"type":"say","who":"孙峻","text":"我梦见…诸葛恪殴打我，等到醒来的时候…我就已经动不了了…"},{"type":"say","who":"孙綝","text":"诸葛恪那个逆贼，到死都还要作怪！"},{"type":"say","who":"孙峻","text":"那不是…重点…重点是…现在只有你…知道我…病倒的消息…"},{"type":"say","who":"孙綝","text":"这是为什么？为什么不让准备出发的骠骑将军或是司徒知道？"},{"type":"say","who":"孙峻","text":"孙家的权力…终归…只能给…孙家人…"},{"type":"say","who":"孙峻","text":"哪怕…是那些人…联合起来…反抗…也在所不惜…"},{"type":"say","who":"孙綝","text":"我只是宗室疏属，位低权轻，更非顾命大臣，没有资格超前于吕据、滕胤，更不敢打破大皇帝遗留的体制。"},{"type":"say","who":"孙峻","text":"蠢啊！如果大皇帝的体制无法保卫大吴？"},{"type":"say","who":"孙綝","text":"（从兄怎么又恢复活力了？！）"},{"type":"say","who":"孙峻","text":"看看北方，曹睿让宗室曹爽与异姓司马懿共同担任托孤大臣，结果司马家反过来吞食曹家。"},{"type":"say","who":"孙峻","text":"大皇帝当初托孤于我与四位异姓，结果那个诸葛恪差点变成第二个司马懿，若不是我果断下手，现在早就变诸葛家专政。"},{"type":"say","who":"孙峻","text":"我把权力集中给自己，滕胤、吕据却不说话，难道他们无欲无求？八成是肖想大皇帝的遗诏，想等我死后接收我的权位。"},{"type":"say","who":"孙峻","text":"所以我要破坏遗命，只有把权力交给孙家人，才能确保孙家安全无虞。就算最后宗室相残，胜利者都是孙家人。"},{"type":"say","who":"孙峻","text":"你一定会遇到很多挑战，绝对要果断。"},{"type":"say","who":"孙峻","text":"曹爽傻傻地想让司马懿自然老死，还被七十一岁的老头反扑，何况吕据他们跟我年纪相近。"},{"type":"say","who":"孙峻","text":"要是你被打倒，以后孙吴宗室的地位恐怕就要一落千丈了"},{"type":"say","who":"孙綝","text":"从兄，我真的能够担当这样的重任？"},{"type":"say","who":"孙峻","text":"我已经向圣上请求任命你都督中外诸军事，只要有兵权，你谁都不需要怕…"},{"type":"say","who":"孙綝","text":"我明白了，这就依照从兄的吩咐，我将继承从兄的地位。"},{"type":"say","who":"孙峻","text":"记得要照顾…大虎…她…在我…死了以后…会很寂寞…"},{"type":"say","who":"孙綝","text":"没问题！"},{"type":"say","who":"孙綝","text":"（搞什么东西，弄到最后居然只是想找个人来帮他照顾那个孙大虎。）"},{"type":"say","who":"孙綝","text":"（我实在是不懂，这种年纪的阿婆有什么吸引力可言。）"},{"type":"say","who":"孙綝","text":"（这么老的也有兴趣，是因为牛肉面煮得好？）"},{"type":"say","who":"孙峻","text":"诸葛恪？！你怎么又过来了？！不要！"},{"type":"say","who":"孙綝","text":"从兄，什么人都没有呀？"},{"type":"say","who":"孙峻","text":"不要啊！不要啊！诸葛恪，不是我想杀你，实在是没有别的选择啊…"},{"type":"say","who":"孙峻","text":"………公元二五六年，丞相孙峻去世后，把权力交给偏将军孙綝，孙綝被任命为侍中、武卫将军、都督中外诸军事。孙綝上任后随即召回进军中的吕据，然而，这样私相授受的人事安排，开始在东吴政界掀起反弹的声浪。吕据之怒吴军营帐"},{"type":"say","who":"吕据","text":"孙綝算什么东西？！小小一个偏将军也敢来下令我班师？"},{"type":"say","who":"唐咨","text":"不管怎么说，他现在也有军权，难道我们不听他的话？"},{"type":"say","who":"吕据","text":"笑话！这样的人事任命有什么正当性可言？孙峻他凭什么把权力传给他从弟？"},{"type":"say","who":"吕据","text":"当初我们几个人都是大皇帝任命的顾命大臣，他死了就该把权力交出来，怎么可以给一个没有顾命大臣身份的人！"},{"type":"say","who":"吕据","text":"现在我决定要上书朝廷，推举司徒滕胤当丞相，也希望各位的帮忙。"},{"type":"say","who":"文钦","text":"（为什么事情会变成这样？北伐就差这一步，居然又卷进这样丑陋的斗争中。）"},{"type":"say","who":"朱异","text":"（你们打死好了，反正这边大都是北方人，那边的孙家也不过是吴郡三流家族，我吴郡朱家没必要和你们耗。）吕据和麾下将领联名上书，推荐司徒滕胤担任丞相。然而孙綝却改命滕胤当大司马，并且派往镇守武昌。吕据知道后更是大怒，立刻派人通知滕胤，要求联合罢黜孙綝。柴桑议事厅东吴激变"},{"type":"say","who":"陆抗","text":"小甘宁，最近发生的这件事情，你有什么看法？"},{"type":"say","who":"甘宁","text":"我没兴趣知道那种无聊的事情，快点陪我玩，不然我会很无聊，无聊到想要写周瑜ｘ鲁肃的男男小说…想看？"},{"type":"say","who":"陆抗","text":"我想要跟另一个小甘宁说话，拜托你可以不要搅局吗？"},{"type":"say","who":"甘宁","text":"真扫兴…你明知道在战场以外的地方叫她会很危险的…好吧，谁叫你是陆逊的儿子。"},{"type":"say","who":"甘宁","text":"什么事情吗？"},{"type":"say","who":"陆抗","text":"这件事情你不觉得是件不得了的大事？"},{"type":"say","who":"甘宁","text":"那又如何？你我人微言轻，既不能有所作为，也不至于受害，这样不就好了。"},{"type":"say","who":"陆抗","text":"可是我大吴从大皇帝崩殂以来，内斗杀戮不断，这样下去，大吴真的会很危险。"},{"type":"say","who":"甘宁","text":"动动脑子吧，你吴郡人有什么理由去淌这浑水？"},{"type":"say","who":"甘宁","text":"当初那帮子北方人撑过了二宫之变，欺压因为二宫之变而伤亡惨重的江东士族，把政权整碗捧去。"},{"type":"say","who":"甘宁","text":"现在他们像呆子一样杀来杀去，对你不正"},{"type":"say","who":"旁白","text":"▶ 是好事？"},{"type":"say","who":"陆抗","text":"这样说来，也不是没有道理…不过缺乏权力继承正当基础的孙綝，为了保护自己，恐怕会把屠刀伸向任何靠近他的人。"},{"type":"say","who":"陆抗","text":"所以我该让陆家人在这个时候从他眼前消失，不然卷进危险就不得了。"},{"type":"say","who":"甘宁","text":"看来你也认为孙綝会赢？"},{"type":"say","who":"陆抗","text":"嗯…因为孙綝的政治斗争经验，比起吕据或是滕胤要丰富很多，那两个人虽然比较有才干，但是斗争却是外行。"},{"type":"say","who":"陆抗","text":"我想不出一个月，孙綝必定发动反击。"},{"type":"say","who":"陆抗","text":"（当年大皇帝对我们吴四姓动手，我们退出权力中心反而躲过这几年的浩劫。这样祸福相倚真是讽刺。）果然不出陆抗所料，孙綝对于吕据和滕胤的行动，展开激烈的反击。首先他命族兄孙宪，率军北上拦截吕据北伐军。接著又派侍中华融和中书丞丁晏，劝告滕胤即刻离开建业。滕胤认为这是孙綝的诡计，拒绝就任，并且扣留住丁晏和华融两人，率众抗战。滕胤一方面指控孙綝谋反，一方面强迫华融写信给孙綝，劝告他退位。孙綝拒绝，上书皇帝孙亮，指控滕胤谋反，并且派兵攻击滕胤。滕胤见状也命丁晏和华融两人假传圣旨，徵召各军，两人不从，当场被斩。此时，孙綝的军队已经逼进滕胤府中，双方在建业的会战一触即发。滕胤遇害建业司徒府"},{"type":"say","who":"滕胤","text":"（我既然已经斩了两位孙綝的心腹，现在情况已经是骑虎难下，我也不能回头再去投降孙綝了。）"},{"type":"say","who":"滕胤","text":"（虽说有人建议我进军苍龙门，但是我这样逼宫，又和孙峻或是孙綝这两个人有什么两样呢？）"},{"type":"say","who":"滕胤","text":"（现在只有等世议的大军赶到，我们再会师诛除这个逆贼。）"},{"type":"say","who":"滕胤","text":"怎么会是你？我的部下呢？"},{"type":"say","who":"孙綝","text":"他们全都跑光，因为你所期盼的吕据大军不会来了。"},{"type":"say","who":"滕胤","text":"什么？！"},{"type":"say","who":"孙綝","text":"蠢货！你以为你斗得过我？如果你知道吕据军队无法赶过来，绝对不会像刚才那样，还谈笑自若呢。"},{"type":"say","who":"滕胤","text":"真可恨，早在孙峻升任丞相，却又不设置御史大夫的时候，我就应该挺身反抗孙峻这家伙。"},{"type":"say","who":"孙綝","text":"你和吕据还不是想著，孙峻死后，大吴就是你们的天下？却没有想过，族兄早就有所安排。"},{"type":"say","who":"滕胤","text":"我如果这样想的话，当初我早就参加诛杀诸葛恪的行动，别把我和你们孙家的小人相提并论！"},{"type":"say","who":"滕胤","text":"我只恨我看走眼，认为孙峻可以拨乱反正，可以阻止诸葛恪的狂乱，所以对他的行动，保持沉默。"},{"type":"say","who":"滕胤","text":"没想到，最后我和吕据沉默的代价，是养出你们两个比诸葛恪狂暴十倍的怪兽！"},{"type":"say","who":"孙綝","text":"随你怎么说，反正你今天要死的命运是不会改变的。"},{"type":"say","who":"滕胤","text":"哼哼哼，大皇帝在天之灵，会好好看著你这个孙家的败类，总有一天会给你最残酷的报应。孙綝率军攻入滕胤府中，滕胤和他部属数十人都被当场格杀。接著，孙綝又屠杀滕胤三族。吕据之死吴军营帐"},{"type":"say","who":"吕据","text":"看见你们两个，我对于自己的下场也该明白了。"},{"type":"say","who":"唐咨","text":"所有的北伐军将士都不会效忠你，大家决定听从圣上讨伐叛贼的诏令。"},{"type":"say","who":"吕据","text":"我吕家两代忠心为孙家。"},{"type":"say","who":"吕据","text":"我爹吕范愿意把所有的希望投注在当时仍然寄人篱下的长沙桓王（孙策），将门下食客百余人都让给他。"},{"type":"say","who":"吕据","text":"我爹后来奉命去迎接武烈皇后（吴国太），哪知道被陶谦当作是袁术的间谍，遭到严刑拷打，最后还是能完成使命。"},{"type":"say","who":"吕据","text":"之后爹随著长沙桓王平定江东，又帮助大皇帝安定后方，临死前还一直嘱托我要为大吴效忠，请问我可能当个叛贼？"},{"type":"say","who":"文钦","text":"我知道你是委屈的，但是现在的情况，已经不是用道理可以说得清的。"},{"type":"say","who":"吕据","text":"我知道，我并不怪你，你有更重要的事情要去完成，不可以死在这里。"},{"type":"say","who":"文钦","text":"（我还要为仲恭复兴魏室怎能死在这里？无论如何都要生存下来，哪怕是被当成懦夫也好。）"},{"type":"say","who":"文钦","text":"（忍耐到获得更重大的胜利为止，这些都是你教我的，对吧，仲恭？）"},{"type":"say","who":"吕据","text":"反而是唐咨你这个家伙，来来回回已经叛变了多少次？人说吕布三姓家奴，你都已经几姓了？"},{"type":"say","who":"吕据","text":"这次倒戈到孙綝那，我想对你来说也不算什么吧。"},{"type":"say","who":"唐咨","text":"哼，死到临头还嘴炮什么。"},{"type":"say","who":"文钦","text":"世议，趁现在逃到魏国吧，我想以你的身分，司马昭没有拒绝你的理由。"},{"type":"say","who":"唐咨","text":"（哼，你说我多姓家奴，我就看你面对生死存亡关头又会怎么做？）"},{"type":"say","who":"吕据","text":"不了，吕据以吕家的忠义为傲，我绝对不会做叛徒。吕据说完随即自杀，之后孙綝仍然将吕据三族屠灭。自此，孙权临终前任命的所有托孤重臣，全部不在人世间了。两个最大的威胁消失后，孙綝开始总揽朝政，不久后被任命为大将军，成为东吴新一代权臣。司马家的新敌人洛阳大将军府"},{"type":"say","who":"司马昭","text":"公闾，这次请你前往寿春一趟，感想如何？"},{"type":"say","who":"贾充","text":"诸葛诞会成为我们的敌人！"},{"type":"say","who":"司马昭","text":"果然…虽说他和我们司马家有姻亲关系，终究他还只是个旧时代的人。"},{"type":"say","who":"司马昭","text":"我请你问的问题是不是太过刺激了？连诸葛诞这种对我们司马家有好感的人都翻脸了，更何况你呢？"},{"type":"say","who":"贾充","text":"大将军，在下已经决定要站到您这边了，对于那个问题，在下的答案您该明白。"},{"type":"say","who":"荀勖","text":"（我们哪有挑边站的权利？现在既然已经跳上贼船，也只有舍命跟到底了。）"},{"type":"say","who":"师纂","text":"（外敌都铲除乾净了，现在就开始针对自己人下手，看来是轮到诸葛诞了。）"},{"type":"say","who":"裴秀","text":"（钟会这家伙因为母丧而缺席，看来现在正是我等表现的大好机会。）"},{"type":"say","who":"贾充","text":"诸葛诞两度镇守扬州，深受部属和人民爱戴，这是非常大的隐忧。"},{"type":"say","who":"贾充","text":"在下建议徵召他回京师，剥夺他的军权。"},{"type":"say","who":"司马昭","text":"还想给他最后一次机会？你的心还真软。"},{"type":"say","who":"贾充","text":"不，在下认为他一定叛变。然今日叛变，灾祸较小，否则拖延下去，灾祸大不可测，不如今天了断。"},{"type":"say","who":"司马昭","text":"说得也是，事情就交给你办了。"},{"type":"say","who":"司马昭","text":"公闾，经过这一次的事情，我可以放心把司马家的背后交给你了。"},{"type":"say","who":"司马昭","text":"过去我爹想结交贾逵而终身不可得，今日我结交他的儿子，也算是完成爹的梦想了吧。"},{"type":"say","who":"司马昭","text":"来，公闾，我敬你一杯。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"贾充","text":"（爹啊，就算您责备我丢了贾家的人，我还是得这样做，我要保护贾家上上下下数十口人的性命啊。）诸葛诞的困惑寿春议事厅"},{"type":"say","who":"诸葛诞","text":"我这几年来，到底在做什么？我到底做了什么事情？"},{"type":"say","who":"蒋班","text":"（怎么回事呀？）"},{"type":"say","who":"焦彝","text":"（我也不知道，似乎从上次贾充来访后，镇东将军就变成这副德行。）"},{"type":"say","who":"诸葛诞","text":"昭伯，太初，平叔…为什么我到现在才明白你们的心？为什么我到现在才看清司马家的真面目？然而这一切都太迟了。半个月前寿春议事厅"},{"type":"say","who":"贾充","text":"在下听说洛阳许多人都希望皇上禅让，不知您怎么看？"},{"type":"say","who":"诸葛诞","text":"你说什么？禅让？"},{"type":"say","who":"旁白","text":"▶ 是的，就是禅让。"},{"type":"say","who":"诸葛诞","text":"（原来司马昭真的想篡位？我一直在助纣为虐？他们竟然欺骗我这么久。）"},{"type":"say","who":"诸葛诞","text":"（身为名士，识人之明居然还比不上那粗鲁的文钦。）"},{"type":"say","who":"诸葛诞","text":"（太初、平叔一定也在笑我。作为四聪八达最后一人，不能这样苟且偷生！）"},{"type":"say","who":"诸葛诞","text":"你不是贾逵的儿子？！世代都受到大魏的恩惠，怎么可以把政权送给别人？"},{"type":"say","who":"贾充","text":"别激动，在下也只是听别人说的。"},{"type":"say","who":"诸葛诞","text":"告诉你！如果洛阳政变，我当以死报答。诸葛诞的困惑寿春议事厅"},{"type":"say","who":"诸葛靓","text":"爹，看您最近愁眉苦脸的样子，要不要出去透透气？"},{"type":"say","who":"诸葛诞","text":"我哪有这个心情。"},{"type":"say","who":"诸葛靓","text":"我听说最近寿春来了个非常灵验的算命师，听说比我们的神算章鱼“宝锣”还准，爹要不要也去给他看一下？"},{"type":"say","who":"蒋班","text":"什么术士这么跩？叫过来就好了。"},{"type":"say","who":"诸葛靓","text":"不不不，那个半仙可不愿意随便给人看相，如果不让他满意，怎么样都叫不过来。"},{"type":"say","who":"诸葛诞","text":"也好，就让我去看看吧。寿春神算寿春城城门"},{"type":"say","who":"诸葛靓","text":"爹，就是这里。"},{"type":"say","who":"诸葛诞","text":"真没想到，所谓的神算…居然是个女人。"},{"type":"say","who":"诸葛果","text":"只要算得准，不管男人或是女人都无妨。"},{"type":"say","who":"诸葛诞","text":"说得也是…只是你真的如传说中算得那么准？"},{"type":"say","who":"诸葛果","text":"正始名士所剩无几，四聪八达只余一人。"},{"type":"say","who":"诸葛诞","text":"你究竟是什么人？"},{"type":"say","who":"诸葛果","text":"你现在走在命运的交叉点上，你充满著彷徨和犹豫。"},{"type":"say","who":"诸葛果","text":"究竟是要成为忠臣，还是要成为开国功臣，你的心中还在摆荡。"},{"type":"say","who":"诸葛诞","text":"………"},{"type":"say","who":"诸葛诞","text":"我看你不是神算，而是利用神算的名号想要吸引我过来见你。"},{"type":"say","who":"赵统","text":"（真的如她说的，诸葛诞会上勾。）"},{"type":"say","who":"赵广","text":"（我就说听诸葛姑娘的准没错。）"},{"type":"say","who":"诸葛果","text":"不久之后，会发生一件逼迫你要做出决定的事情，我正是为了帮助你做出正确决定而来的。"},{"type":"say","who":"诸葛诞","text":"呵呵…可以告诉我，你究竟是谁了吧。"},{"type":"say","who":"诸葛果","text":"琅邪诸葛家，一门三方为冠盖，天下荣之。"},{"type":"say","who":"诸葛诞","text":"（等一下，如果说她也和诸葛家有关系的话，扣除掉已经灭门的东吴诸葛家，那么就只剩下蜀地…）"},{"type":"say","who":"诸葛诞","text":"（该不会…她和那个名满天下的从兄有关系？）寿春三叛寿春议事厅"},{"type":"say","who":"诸葛诞","text":"真是没有想到，能够在这里见到从未谋面的蜀地诸葛家人。"},{"type":"say","who":"蒋班","text":"这样好吗？虽说眼前是个看起来没有威胁性的弱女子，但她是蜀人也是事实。"},{"type":"say","who":"诸葛诞","text":"那又如何？她是我的亲戚，过去我想见从兄而不可得，现在能见到他女儿也算得偿所愿。"},{"type":"say","who":"焦彝","text":"（平白无故跑来这边，一定有问题。不过，既然是蜀人，应该也不会去劝将军效忠司马家，可以好好观察一下。）"},{"type":"say","who":"诸葛诞","text":"等一下，似乎有人来了…士兵恭喜镇东将军！"},{"type":"say","who":"诸葛诞","text":"有什么事情好恭喜的？士兵朝廷徵召您回到洛阳担任司空，能够升到三公位置，小人还能不恭喜？"},{"type":"say","who":"诸葛诞","text":"朝廷有说什么时候出发？士兵似乎是希望您即刻出发，而且在出发前，请将兵权移交给扬州乐刺史。"},{"type":"say","who":"诸葛诞","text":"好，我知道了。"},{"type":"say","who":"诸葛靓","text":"恭喜爹您升官了。"},{"type":"say","who":"诸葛诞","text":"恭喜个屁！我快大祸临头了。"},{"type":"say","who":"诸葛诞","text":"我当三公的顺序，不管怎么样都会在王昶之后，现在又只派一个小兵来传令，怎么想都和乐綝脱离不了关系。"},{"type":"say","who":"诸葛诞","text":"你们说我该去，还是不该去？"},{"type":"say","who":"诸葛果","text":"夏侯太初的事情，似乎距离现在还不久。"},{"type":"say","who":"诸葛诞","text":"夏侯太初？！对呀…这个该死的司马昭，居然完全不念我们之间的关系。"},{"type":"say","who":"蒋班","text":"大将军从来就没有信任过您，不然他就不会派贾充来探您口风了。"},{"type":"say","who":"焦彝","text":"当初就说过帮司马家是大错特错，现在灾难临头才知道了吧。"},{"type":"say","who":"诸葛诞","text":"你们两个最近说话越来越不留余地。"},{"type":"say","who":"诸葛诞","text":"我被司马家蒙骗了，一直以来，我以为司马家只是想要夺得权力来保护自己，从来没想过他们会有篡位的念头。"},{"type":"say","who":"诸葛果","text":"真的没想过？"},{"type":"say","who":"诸葛诞","text":"什么？"},{"type":"say","who":"诸葛果","text":"当司马懿屠杀曹爽的时候，你真的没想过司马家的夺权行动已经变质？"},{"type":"say","who":"诸葛果","text":"当司马师废黜皇帝的时候，你真的没想过他已经在觊觎皇帝位子？"},{"type":"say","who":"诸葛果","text":"当毌丘俭起兵的时候，你真的没想过哪边"},{"type":"say","who":"旁白","text":"▶ 是真正的忠臣？"},{"type":"say","who":"诸葛诞","text":"这……"},{"type":"say","who":"诸葛诞","text":"（虽是女子，但是分析字字在理，真不愧"},{"type":"say","who":"旁白","text":"▶ 是从兄的女儿。）"},{"type":"say","who":"诸葛果","text":"现在是做出决定的时候，是要维护名士风范，还是苟且偷生，决定权都在你。"},{"type":"say","who":"诸葛诞","text":"………"},{"type":"say","who":"诸葛诞","text":"（这么多年来，我被自己的贪心给蒙蔽了，明明有那么多明显的事实摆在眼前，我就是不肯相信司马家有逆心。）"},{"type":"say","who":"诸葛诞","text":"（是呀，我官位节节高升，还成为司马家的姻亲，但我却失去了一个名士该有的气节。）"},{"type":"say","who":"诸葛诞","text":"（我过著行尸走肉的日子却不自知，还因为自己选对边站而沾沾自喜，诸葛公休啊…你比起你在蜀地的从兄差太多了。）"},{"type":"say","who":"诸葛诞","text":"（就算现在为时已晚，司马家势力已经是庞大到难以对抗，我还是要做我该做的事情。）"},{"type":"say","who":"诸葛诞","text":"我已经决定了！我诸葛诞不是司马家的家奴，我是四聪八达的最后一人！我要成为正始名士最后的典范！"},{"type":"say","who":"诸葛诞","text":"现在即刻把扬州刺史乐綝抓过来，那家伙随时会成为司马昭的内应。乐綝的抉择扬州议事厅"},{"type":"say","who":"庞会","text":"诸葛诞叛军已经快要杀进来了，您难道不准备逃走？"},{"type":"say","who":"乐綝","text":"你先走吧，你一个人还有机会逃出去。"},{"type":"say","who":"庞会","text":"可是…"},{"type":"say","who":"乐綝","text":"别在这时候还想要效法你父亲，别忘记你还有更重要的使命。"},{"type":"say","who":"庞会","text":"是呀…我还没有对关羽一家人复仇。"},{"type":"say","who":"乐綝","text":"那你还不快走！"},{"type":"say","who":"庞会","text":"请您多保重。"},{"type":"say","who":"乐綝","text":"（这个庞会，虽然武勇和胆识都不逊于他父亲庞令明，但只为复仇而活，已经葬送掉他的人生了。）"},{"type":"say","who":"乐綝","text":"（唉…我还去关心他呢，自己都快性命不保了。）半个月前洛阳附近"},{"type":"say","who":"乐綝","text":"哈哈哈，我终于升到扬州刺史啦，羡慕我吧，忌妒我吧！"},{"type":"say","who":"张虎","text":"哼，这种屎缺，送给我都不要。"},{"type":"say","who":"乐綝","text":"我就知道张辽的儿子说不出什么好话，你坦率点敬佩我会怎样？"},{"type":"say","who":"戴陵","text":"两位别吵了啦，想想你们也吵了几十年，不觉得这是了不起的孽缘？"},{"type":"say","who":"乐綝","text":"是呀，回想起过去这家伙小时候，居然把我拿来当做点心的梨子偷吃掉。"},{"type":"say","who":"张虎","text":"我倒记得有人专门抢我女朋友，我把哪个妹，你就去把哪个。"},{"type":"say","who":"乐綝","text":"哼，你还敢说？你上次偷我头盔，我还没找你算帐。"},{"type":"say","who":"张虎","text":"那是报复你上次偷用我的黄龙钩镰刀。"},{"type":"say","who":"张虎","text":"乐进的儿子，这个扬州刺史的职务绝对不好做，你该知道你不是司马家的亲信。"},{"type":"say","who":"乐綝","text":"我又何尝不知道？司马家对淮南诸葛诞不放心，所以想找个不亲近诸葛诞，却又死了也没关系的人去那边牵制他。"},{"type":"say","who":"张虎","text":"你既然知道，为什么还要去赴任？"},{"type":"say","who":"乐綝","text":"我能有选择吗？现在这个时候，有谁可以违抗司马家的意思？"},{"type":"say","who":"戴陵","text":"回想起过去，我们三个人还可以公然鄙视司马懿，现在居然连对司马家稍微吭一声都不行。"},{"type":"say","who":"乐綝","text":"如果爹或是张辽还在的话，哪可能轮到这些人嚣张？"},{"type":"say","who":"张虎","text":"乐綝，不要死了！等你从扬州回来，我还想和你好好喝一杯。"},{"type":"say","who":"乐綝","text":"哼，我可是不死身的乐綝，你就把你的酒给我准备好吧。乐綝的骨气寿春议事厅"},{"type":"say","who":"乐綝","text":"诸葛诞，你身受朝廷大恩，怎么敢造反，袭击朝廷命官？"},{"type":"say","who":"诸葛诞","text":"这才是我要对你说的，你父亲乐进是武帝最信赖的将领之一，对大魏忠心耿耿。"},{"type":"say","who":"诸葛诞","text":"怎么到你这代，变成司马家的走狗！"},{"type":"say","who":"乐綝","text":"诸葛诞，我只问你一次，你究竟是真心想要起兵匡复魏室，还是想要自保而已？"},{"type":"say","who":"诸葛诞","text":"你这司马家的走狗，凭什么问我这个！"},{"type":"say","who":"乐綝","text":"司马懿滥杀宗室，司马师擅行废立，司马昭妄想篡逆，这些事情我也知道。"},{"type":"say","who":"乐綝","text":"可叹武帝时的名将，只要有一人在此，又怎么可能轮到他们在那猖狂。"},{"type":"say","who":"诸葛诞","text":"等一下，你是支持我起兵？"},{"type":"say","who":"乐綝","text":"如果你是真心想要起兵，我又怎么可能不支持，我是乐文谦的儿子，就算能力再差，我也有我的骨气。"},{"type":"say","who":"乐綝","text":"但是…我没有办法抛下我的妻儿不顾，我的肇儿还年幼，我不希望他因为我而被牵连。"},{"type":"say","who":"乐綝","text":"所以请你杀我，这样我麾下的军队都可以归你统率。"},{"type":"say","who":"诸葛诞","text":"为什么你要做到这种地步？"},{"type":"say","who":"乐綝","text":"我乐綝浑浑噩噩过了数十年，从来没有为大魏做任何一件事，今天只要用我的血，就可以拯救大魏，我何乐不为？"},{"type":"say","who":"诸葛诞","text":"你真的不再考虑和我一起起义？"},{"type":"say","who":"乐綝","text":"祝你起兵顺利，推翻司马家，让武帝建立的大魏回复原有的光彩。"},{"type":"say","who":"乐綝","text":"（张虎，原谅我不能和你喝一杯了，只希望你能体会我的苦心，不要像我这样，到现在无奈只能用这种方式来报效大魏。）公元二五七年，朝廷下诏诸葛诞担任司空，命返洛阳就职。诸葛诞接到诏书后，决意起兵，斩杀扬州刺史乐綝，合并其部队。诸葛诞一口气聚集淮河南北各县的屯垦部队十余万，及扬州精兵四五万人，，积存粮食够供应大军一年使用。诸葛诞决意闭城自守，在寿春城作长期抗战的准备。勇气寿春诸葛府"},{"type":"say","who":"诸葛靓","text":"明天我就要以人质的身分前往东吴，所以现在特别向各位辞行。"},{"type":"say","who":"赵统","text":"人质？难道你们要向东吴投降？"},{"type":"say","who":"诸葛靓","text":"应该是这样没错。"},{"type":"say","who":"赵统","text":"这实在是太奇怪了！不是说要起兵反司马家吗？为什么反而要降东吴，把敌人引进自己的国土？"},{"type":"say","who":"诸葛靓","text":"对不起，有件事情我一直想问外姊您，您身后的这两位将军是谁？"},{"type":"say","who":"赵统","text":"忘记自我介绍，在下赵云之子赵统。"},{"type":"say","who":"赵广","text":"同样是赵云之子，也是赵统之弟赵广。"},{"type":"say","who":"诸葛靓","text":"原来是名满天下赵云将军的儿子，失敬失敬。"},{"type":"say","who":"诸葛靓","text":"说实话，我也不知道爹到底在想什么，既然要起兵反正，就应该大张旗鼓向各地号召响应，怎么能这样投降敌人。"},{"type":"say","who":"赵广","text":"我想应该和过去毌丘俭失败，知道指望各地响应是没用的关系吧。"},{"type":"say","who":"赵广","text":"更何况，过去诸葛将军的立场反反覆覆，一下子帮司马师，现在又反司马昭，这样怎么可能有号召力？"},{"type":"say","who":"诸葛果","text":"其实问题没有那么复杂，单纯是族叔在迷惘而已。"},{"type":"say","who":"诸葛靓","text":"迷惘？因为姊姊的关系？毕竟她也是司马家的媳妇。"},{"type":"say","who":"诸葛果","text":"或许是，只是要想到对抗这个权大势大的司马家，任谁不会感到恐惧呢？特别是之前还仰仗司马家权势的他。"},{"type":"say","who":"诸葛果","text":"不过不要紧，族叔已经踏出最勇敢而且艰钜的一步，剩下就静观其变就好。"},{"type":"say","who":"赵统","text":"可是…"},{"type":"say","who":"诸葛果","text":"我们的目的是要拯救诸葛诞的内心，现在既然他都已经觉醒，我们又何必再多计较呢？"},{"type":"say","who":"诸葛果","text":"你的父亲是伟大的，我也以这个族叔为荣，只要记住这点就好。"},{"type":"say","who":"赵广","text":"（我一直以为，诸葛姑娘来这边的目的，是要煽动诸葛诞造反，好缓和我大汉现在危险的情势，难道不是这样？）"},{"type":"say","who":"赵统","text":"（我真的不懂，如果诸葛诞这次起兵弄成这样的话，我们大汉哪可能再度有起兵的机会？）东吴发兵建业大将军府"},{"type":"say","who":"孙綝","text":"诸葛诞把他的儿子送来当人质，还向我们大吴称臣。"},{"type":"say","who":"孙綝","text":"现在如果我们得到寿春，将可以让大吴的领土，一口气拓展到淮南一地，这可是过去大皇帝所没有做到的事情。"},{"type":"say","who":"孙綝","text":"因此，我决定亲自率军增援诸葛诞，武昌方面就由镇南将军朱异率军增援。"},{"type":"say","who":"鲁淑","text":"在下认为这件事情应该要从长计议才是，现在我大吴内部也不稳，夏口督孙壹才刚刚叛逃，我军军心需要时间回复。"},{"type":"say","who":"孙綝","text":"孙壹那个小人物不值一提，曹贼居然还把他当宝，我看司马昭那家伙真是蠢得可笑。"},{"type":"say","who":"孙綝","text":"（虽然从兄为了保卫孙家人才传位予我，但我还是要排挤可能威胁我的宗室近亲，才能确保我这疏属的权位。）"},{"type":"say","who":"鲁淑","text":"不，那是可怕的政治号召作战，想想连个孙壹都可以获得礼遇，更何况是其他高官？"},{"type":"say","who":"孙綝","text":"住口！要是有人敢效法孙壹，我就会让他死得比孙宪或是王惇还惨！"},{"type":"say","who":"鲁淑","text":"（大将军现在已经是杀红了眼，为了他的权力，杀掉吕据和滕胤不说，甚至连孙峻时代得宠的孙宪都杀。）"},{"type":"say","who":"鲁淑","text":"………"},{"type":"say","who":"孙綝","text":"（若不是他是鲁子敬的儿子，我早就把他宰了。幸好他识相，不再说下去。）"},{"type":"say","who":"孙綝","text":"我想镇北大将军应该很熟悉寿春的情况，我希望你能带领三万军队，先行去支援寿春。"},{"type":"say","who":"文钦","text":"等一下，大将军不知道我和诸葛诞的关系非常恶劣？"},{"type":"say","who":"孙綝","text":"大敌当前，我认为你们应该可以和睦相处才是，难道你会为了私怨而不顾大局？"},{"type":"say","who":"文钦","text":"不，您说的是，我愿意率军先行援救诸葛诞。"},{"type":"say","who":"文钦","text":"（忍耐，为了昭伯和仲恭的理想，我一定要忍耐。）"},{"type":"say","who":"孙綝","text":"那么唐咨、于诠和全怿等人，也跟随去援救寿春。"},{"type":"say","who":"全怿","text":"等一下，我也要去？"},{"type":"say","who":"孙綝","text":"废话！你以为你姓全就有特权？我和从兄不同，不管是谁，都会一视同仁对待！"},{"type":"say","who":"全怿","text":"（我苦啊，似乎这个大将军一开始就对我们全家有意见，娘说的话对他也没有任何用处，我们全家早晚要倒楣了。）"},{"type":"say","who":"孙綝","text":"（哼，我才不像族兄，胃口好到连那种年纪的阿婆都吃得下去，全家那群废物，既无用又占满高位，早晚干掉他们。）公元二五七年，东吴在诸葛靓作为人质，到达东吴以后，，皇帝孙亮即刻任命诸葛诞为大司徒、骠骑将军和青州刺史。大将军孙綝派遣镇北大将军文钦，率领三万人先行出发，援救寿春（淮南）。孙綝本人也率领大军挺进，并指挥武昌的朱异和丁奉等人朝向寿春出发。出兵平乱洛阳大将军府"},{"type":"say","who":"司马昭","text":"诸葛诞果然造反了，我在计画上稍微加点料，引诱他杀了乐綝，这下他再也无法回头了。"},{"type":"say","who":"司马昭","text":"不过他真是差毌丘俭一大截，仗都没打就投降东吴，还敢说自己是忠臣义士？"},{"type":"say","who":"司马昭","text":"我将率领大军，亲自平定诸葛诞乱事，并且顺道让吴贼再也无进军淮南的实力。"},{"type":"say","who":"司马昭","text":"让镇南将军王基代镇东将军，都督扬豫州诸军事。"},{"type":"say","who":"司马昭","text":"安东将军陈骞和豫州刺史州泰会同王基平乱。"},{"type":"say","who":"司马昭","text":"荆州刺史鲁芝和青州都督石苞也同时率军支援，这样动员人数应该可超过二十万。"},{"type":"say","who":"贾充","text":"王基和鲁芝可以信赖吗？他们曾经担任过曹爽的部属…"},{"type":"say","who":"司马昭","text":"公闾呀…上次能够平定毌丘俭叛变，如果没有伯舆的力量，根本不可能办到。"},{"type":"say","who":"司马昭","text":"我信任他们，就如同信任公闾你一样，请不要再怀疑他们的忠诚了。"},{"type":"say","who":"钟会","text":"大将军…"},{"type":"say","who":"司马昭","text":"士季呀，虽说这次激反诸葛诞为我所愿，但你说的也不无道理。"},{"type":"say","who":"司马昭","text":"其实诸葛诞年事已高，只要等他死亡即可，不需要去激反他制造国家的危难。"},{"type":"say","who":"司马昭","text":"要是早点接到你的信，或许我不会派公闾去见诸葛诞。"},{"type":"say","who":"钟会","text":"过去的事情就算了，现在应该是想办法尽快平乱才是。"},{"type":"say","who":"司马昭","text":"关于令堂的丧事，已经办好了？"},{"type":"say","who":"钟会","text":"没问题了，比起对母亲的小孝，我想要对大将军尽大孝，相信母亲的在天之灵也能理解我的作为。"},{"type":"say","who":"钟会","text":"这次大将军准备得非常周到，但是您似乎忘记做一件事了。"},{"type":"say","who":"钟会","text":"您打算亲自征讨诸葛诞，无疑是最正确的选择，然而上次的教训不可忘。"},{"type":"say","who":"司马昭","text":"上次的教训…哎呀，我还真差点忘记了。"},{"type":"say","who":"司马昭","text":"这就请求圣上和太后一起随同出征，另外，也把东乡公主给我一并带上。"},{"type":"say","who":"钟会","text":"（从他少见的慌张神情看来，似乎当时那件事情，对大将军还是梦魇一场。）"},{"type":"say","who":"司马昭","text":"士季，做得好！你真是我的张子房啊。"},{"type":"say","who":"荀顗","text":"（那不是当初武帝夸赞我老爹的话？大将军说这话，可把他的野心表露得一览无遗呀。）"},{"type":"say","who":"裴秀","text":"（这个钟会，他什么时候这么得到大将军的信任了…明明是我比较早跟随大将军，现在却完全落后了。）忍辱负重洛阳宫殿"},{"type":"say","who":"曹髦","text":"姑姑，司马昭实在是太过分了！居然要把朕、太后和您带著去征讨诸葛诞！"},{"type":"say","who":"曹髦","text":"朕很清楚诸葛诞起兵是为了推翻司马家，然而朕却得窝囊地帮著打对朕忠心的人，这实在是难以忍受！"},{"type":"say","who":"曹绫","text":"司马昭记取了上次的教训，所以有这样的行动，我并不意外。"},{"type":"say","who":"曹绫","text":"诸葛诞一开始就退缩，闭城自守又投降东吴，已经失掉先机，司马昭此举还有压抑住其他亲魏室将领的效果。"},{"type":"say","who":"曹髦","text":"可恶！难道就任他摆布？"},{"type":"say","who":"曹绫","text":"现阶段来说，我也只能这样说，我们只能乖乖听他的话。"},{"type":"say","who":"曹绫","text":"我不是说过，一定要忍，因为你有著远远超过司马昭的年轻活力。"},{"type":"say","who":"曹髦","text":"可是，每次想到武皇帝的武功，朕就觉得朕实在是没用到家。"},{"type":"say","who":"曹绫","text":"你错了，自从昭伯和他的势力覆亡之后，我们和司马家的实力就完全逆转过来。"},{"type":"say","who":"曹绫","text":"纵然是祖父复生，恐怕也很难击倒司马家。"},{"type":"say","who":"曹绫","text":"你也不要妄自菲薄，现在毕竟是形势比人强，我们能做的，就只有忍耐而已。"},{"type":"say","who":"旁白","text":"▶ 是…"},{"type":"say","who":"曹髦","text":"（姑姑，我虽然很尊敬您，但是只有这点我不同意。我认为如果是武皇帝，一定会拔刀和司马家一搏，这才是英雄作为。）公元二五七年，六月二十五日，曹魏皇帝曹髦和太后一行人抵达项县，司马昭则统率各路大军二十六万，进抵丘头。然而司马昭布置的包围网还没有完成，东吴的援军，文钦等人已经抵达，从寿春城东北，沿八公山挺进，全体入城。吴越同舟寿春议事厅"},{"type":"say","who":"诸葛诞","text":"………"},{"type":"say","who":"文钦","text":"………"},{"type":"say","who":"唐咨","text":"怎么气氛那么僵？"},{"type":"say","who":"蒋班","text":"（东吴这帮傻鸟似乎还不知道这两人之前结怨有多深吧。）"},{"type":"say","who":"诸葛诞","text":"想不到孙大将军会派出这么强力的援军，我是该感激他吗？"},{"type":"say","who":"文钦","text":"文钦奉命来协助防守寿春城，一切谨遵诸葛将军指示。"},{"type":"say","who":"诸葛诞","text":"仲若，想不到我们会有携手合作的一天。"},{"type":"say","who":"文钦","text":"如果我们早点携手合作的话，现在我们应该在洛阳，和仲恭一起辅佐圣上。"},{"type":"say","who":"焦彝","text":"（哇勒，这两个人是想要当场干起来？）"},{"type":"say","who":"文钦","text":"不过…因为你的起义，让我有机会重新回到这熟悉的土地上，贯彻对抗司马家的大义。"},{"type":"say","who":"文钦","text":"关于这点，我还是很感激你。"},{"type":"say","who":"诸葛诞","text":"（这个莽夫居然变得这么会说话，要是早点这样，我也不至会这么讨厌他。）"},{"type":"say","who":"文钦","text":"（为了再次高揭大魏的大义，为了成就毌丘仲恭未完成的志业。寿春城啊，我回来了！）王基的坚持寿春魏军营帐"},{"type":"say","who":"陈骞","text":"现在大将军的主力部队没有到，我们如果和敌人硬碰硬，应该是没有赢的机会。"},{"type":"say","who":"陈骞","text":"（你想死我才不管你，我可是要留著命去嫖妓的。）"},{"type":"say","who":"王基","text":"休渊，你的想法非常正确，但还是有修正的空间。"},{"type":"say","who":"王基","text":"先不说城内十几万的部队，城外在附近游击的朱异部队，才是我们真正该烦恼的对象。"},{"type":"say","who":"陈骞","text":"是呀，那个朱异也知道不要和我们正面对决，只是停留在外围，和城内军队相呼应而已。"},{"type":"say","who":"王基","text":"大将军虽然命我们坚守，但是如果不先解决掉朱异的军队，要固守几乎是不可能的任务。"},{"type":"say","who":"使者","text":"启禀镇南将军，圣上下诏要您进据八公山。"},{"type":"say","who":"王基","text":"现在我军包围网已经完成，营垒坚固，只要加强防御工事，严密提防他们逃走就行了。"},{"type":"say","who":"王基","text":"如果转移阵地，使贼寇逃出城外，以后就是再有本事的人，恐怕也难以收拾残局。"},{"type":"say","who":"使者","text":"可圣上的命令…"},{"type":"say","who":"王基","text":"我拒绝执行这样的命令，就这样对圣上说吧。"},{"type":"say","who":"王基","text":"和贼寇对峙，应该像大山一样，毫不动摇。如果迁到险要之处，军心动荡，声势就已经居下风。"},{"type":"say","who":"王基","text":"现在各军都已经进入深沟高垒之中，人心笃定，不应该使他们受到搅扰，这是作战的要领。王基的奏章，不久之后被批准。王基开始加强对寿春的包围网，里外数重，壕沟深陷，营垒坚固。文钦等人数次尝试突围，都遭到王基迎头痛击，被驱赶回城里面。破敌方案寿春魏军营帐"},{"type":"say","who":"司马昭","text":"伯舆，若不是你的择善固执，恐怕现在寿春防线就被敌人突破了。"},{"type":"say","who":"王基","text":"现在敌人已经被彻底赶回城内，短时间内不可能再出击。"},{"type":"say","who":"王基","text":"我认为应该趁著敌人士气受挫的机会，一口气攻陷寿春城！"},{"type":"say","who":"石苞","text":"我也认为应该发动攻势，这样就可以解救寿春的妇女同胞！"},{"type":"say","who":"司马昭","text":"咳…我们是奉旨讨贼，你难道又在动什么歪脑筋？"},{"type":"say","who":"石苞","text":"没什么啦，我最近身体虚弱，需要十个八个女人陪睡。"},{"type":"say","who":"司马昭","text":"（这个石仲容虽然长得好看，头脑又聪明，但是个性轻浮又好色成性，难怪爹当年不肯重用他。）"},{"type":"say","who":"司马昭","text":"（大哥只是想他虽然人品差，但也有些经国才略，就姑且一用，只是这人真的值得我们司马家败坏名声也要用？）"},{"type":"say","who":"司马昭","text":"寿春城坚固，而且守军众多，攻城一定会受到挫折，如果外援再来，正好腹背受敌，是危险的策略。"},{"type":"say","who":"司马昭","text":"而今，文钦、诸葛诞和唐咨这三个叛徒聚集在一个孤城中，这是上天要他们一起被诛杀。"},{"type":"say","who":"司马昭","text":"我们应该紧密包围三面，如果吴贼从陆地赴援，粮食携带不便，数量也有限，我们用轻装骑兵切断粮道，不战即可退敌。"},{"type":"say","who":"司马昭","text":"只要能击破吴贼援军，城内的贼寇必定会束手就擒。"},{"type":"say","who":"王基","text":"话虽如此，但城外朱异的游击部队该怎么处理？如果不收拾掉他，我们很难专心进行包围行动。"},{"type":"say","who":"张虎","text":"让我去！我要杀光吴贼和诸葛诞一干人等！"},{"type":"say","who":"司马昭","text":"不行！你身为名将之后，也该知道光凭血气之勇，无法破敌。"},{"type":"say","who":"张虎","text":"（我恨呀，司马家根本不信任我，可我为了帮乐綝你报仇，却又不得不委身在他们底下。）"},{"type":"say","who":"鲁芝","text":"（没想到这次居然得率军帮司马家作战，在座的不知道有多少人是过去曹大将军的部属，现在看来真是讽刺。）"},{"type":"say","who":"鲁芝","text":"（不过他对我们也不完全放心，不然就不会当场诛杀常林的儿子给我们看。）"},{"type":"say","who":"鲁芝","text":"（想起当初司马懿对常林再三敬拜，司马昭却把他儿子像杀猪一样杀掉，他杀我们更不会犹豫。）"},{"type":"say","who":"司马昭","text":"朱异怎么说也是吴贼顶尖名将之一，可能得劳驾伯舆你了。"},{"type":"say","who":"曹绫","text":"大将军，对付那样的部队，你不需要派出我军的王牌。"},{"type":"say","who":"胡奋","text":"这不是公主吗？怎么会出现在这个地方？"},{"type":"say","who":"司马昭","text":"是我要她来的，她的文韬武略和爹可说是不相上下，对于破贼一定会有所帮助。"},{"type":"say","who":"司马昭","text":"（放著你待在圣上身边才更危险，只有把你紧紧扣在我身边，我才可以放心。）"},{"type":"say","who":"陈泰","text":"（现在的我和公主的立场没有任何差别，都是因为不信任被紧紧扣在身边呀。）"},{"type":"say","who":"陈泰","text":"（子上，我知道你想要给我机会，希望我能表现出恭顺的态度。但是很可惜，我做不到。）"},{"type":"say","who":"曹绫","text":"我认为，奋武将军石苞有勇有谋，足够对付朱异。"},{"type":"say","who":"胡烈","text":"太夸张了吧，那个好色鬼能够做什么？"},{"type":"say","who":"司马昭","text":"不，记得东关大败的时候，只有仲容的军队能够全身而退，或许他真的有才能。"},{"type":"say","who":"司马昭","text":"（能屈能伸？也对，虽说我不能明目张胆杀她，但是直接囚禁她也不难…她应该是用具体行动表示自己和叛军无关吧。）"},{"type":"say","who":"司马昭","text":"仲容！你带著州泰和胡烈等人去迎击朱异，我会把帐下最精锐的部队交给你。"},{"type":"say","who":"石苞","text":"是的！我一定会战胜朱异！"},{"type":"say","who":"石苞","text":"（呵呵，东吴听说女将多，趁机带两个来治疗我的性饥渴。）"},{"type":"say","who":"州泰","text":"石将军！你最好收敛点！我平常劝谏你的话可从来没有少过。"},{"type":"say","who":"石苞","text":"（这州泰正经八百的，真是讨人厌，我就不相信摆两个大奶妹在身边你不要。）"},{"type":"say","who":"石苞","text":"（不过说真的，眼前这个公主真是正翻了，打赢的话，可以请她亲自慰劳我？）"},{"type":"say","who":"胡烈","text":"（瞧他这副色咪咪的样子，真的能够打仗？真羡慕大哥可以待在大将军身边。）石苞率领的分队，完全不辜负司马昭的期望，由州泰在阳渊给予朱异部队迎头痛击，州泰继续追击，杀伤两千余人。石苞之才寿春魏军游击军营帐"},{"type":"say","who":"石苞","text":"怎么？！你们两个人看我，怎么还有怀疑的眼神？仗不是都打赢了？"},{"type":"say","who":"胡烈","text":"走运。"},{"type":"say","who":"州泰","text":"实际出兵的可是我，石将军你唯一做的事情，是在后面捡吴贼败军的物资。"},{"type":"say","who":"石苞","text":"啊…就…济贫嘛。"},{"type":"say","who":"州泰","text":"喂，现在贼首孙綝亲自率军来到，朱异这次获得完全的补给，实力可不同凡响。"},{"type":"say","who":"州泰","text":"偏偏你却无动于衷，只知道在这边吃喝玩乐，想找死，不要拖著我一起下水！"},{"type":"say","who":"石苞","text":"你一定是觉得我这个人人品低劣，只是靠著运气升到今天的高位。"},{"type":"say","who":"州泰","text":"我可没这样想。"},{"type":"say","who":"石苞","text":"你有没有想过为什么过去太傅赏识你，轻蔑我，到最后我却爬得比你高的原因？"},{"type":"say","who":"石苞","text":"比道德，你我这种平民出身的，怎么样也比不过儒学世家子弟，这点我想曾经被那钟会羞辱过的你也该很清楚。"},{"type":"say","who":"石苞","text":"所以不如放纵自己，反正我是没水准的死老百姓，贪财好色都是应该的。"},{"type":"say","who":"石苞","text":"而正因为我好色又贪吝，只是个胸无大志的废物，所以不更让人放心？"},{"type":"say","who":"州泰","text":"（等一下…莫非他是效法王翦？）"},{"type":"say","who":"石苞","text":"嘿嘿嘿…听说东吴专出正妹，到时候要是抓到朱异，逼他们用十个美女和我交换俘虏。"},{"type":"say","who":"州泰","text":"（我多心了，他根本骨子里就是个大淫棍。）"},{"type":"say","who":"胡烈","text":"我认为应该率军去突袭吴贼的粮草所在，只要切断他们粮草供应，要打败一群饿坏了的兵士，并不困难。"},{"type":"say","who":"石苞","text":"好是好，但你知道粮草的位置？"},{"type":"say","who":"胡烈","text":"总会找得到…"},{"type":"say","who":"石苞","text":"真是的…就在都陆一带。"},{"type":"say","who":"胡烈","text":"咦？"},{"type":"say","who":"石苞","text":"你真当我坐在这边什么都不做？从上次交手就知道那家伙无心作战，只是稍微晃一下就回去，所以把粮草放在后方。"},{"type":"say","who":"石苞","text":"不过这次，我要让他的安排，变成毁灭他部队的致命伤。"},{"type":"say","who":"石苞","text":"命你率领五千精兵，袭击都陆，摧毁朱异的粮草供应。"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"石苞","text":"还有…"},{"type":"say","who":"石苞","text":"如果发现什么宝贝，记得要带回来，我要济贫。"},{"type":"say","who":"胡烈","text":"……孙綝再命朱异率领丁奉等人，前去援救寿春。朱异把辎重粮秣，留在都陆，自己率军挺进到黎浆。石苞再度迎击，击破朱异。朱异残兵陷入饥饿状态，沿途吃树叶充饥，勉强回到孙綝大营。朱异殉难吴军营帐"},{"type":"say","who":"孙綝","text":"搞什么东西，你们吴郡朱家部曲不是号称所向无敌，怎么打成这副德行？"},{"type":"say","who":"朱异","text":"这场战争根本就是大错！人家魏贼家里面的事情，为什么要牵连到我们？"},{"type":"say","who":"孙綝","text":"难道你想放弃寿春？这可是拿下寿春的大好机会。"},{"type":"say","who":"朱异","text":"别开玩笑了，寿春距离魏贼京城近，地势又是一片平坦，适合骑兵行进，我军以步军和水军为主，根本无法守住那里。"},{"type":"say","who":"孙綝","text":"你是在质疑我的方针？"},{"type":"say","who":"朱异","text":"我不希望朱家子弟在这样的战场上牺牲。"},{"type":"say","who":"陆抗","text":"（这些话，真是说到我心坎里了。这场战争，对我江东大族根本毫无意义，守也守不住，得到的人力也有限。）"},{"type":"say","who":"孙綝","text":"现在就率领你的部队，给我好好打一仗！"},{"type":"say","who":"朱异","text":"我拒绝！我的部队才刚从饥饿状态中逃出来，根本就没有战斗力。"},{"type":"say","who":"孙綝","text":"我再说最后一次，给我出战！"},{"type":"say","who":"朱异","text":"我拒绝！既然你口口声声说要拿下寿春，为什么你的军队却从来没有动一下。"},{"type":"say","who":"孙綝","text":"我有我的考量。"},{"type":"say","who":"孙綝","text":"（这场战争，我本来就只打算让朱异的部队去打，我才不会像诸葛恪那么笨，把自己手上的筹码都败光。）"},{"type":"say","who":"孙綝","text":"（现在我离开建业也有一段时间，全家班的人在背后给我搞鬼的话，事情就变得很麻烦，看来是要赶快回军建业为上策。）"},{"type":"say","who":"丁奉","text":"季文！不要这样固执！就听大将军的话吧。"},{"type":"say","who":"朱异","text":"过去大皇帝也从没有这样命令过父亲，你凭什么这样命令我吴郡朱家！"},{"type":"say","who":"孙綝","text":"吴郡朱家？笑死人了，我谁没杀过，怕你小小的吴郡朱家？"},{"type":"say","who":"丁奉","text":"不可呀，再怎么说，吴郡朱家都是我大吴的支柱。"},{"type":"say","who":"孙綝","text":"放屁！我就不相信，这个吴郡朱家能有多大本事！"},{"type":"say","who":"丁奉","text":"大将军，拜托您三思呀。"},{"type":"say","who":"孙綝","text":"来人！"},{"type":"say","who":"孙綝","text":"把这个违抗军令的逆贼给我拖下去砍了！"},{"type":"say","who":"丁奉","text":"大将军，季文是威镇国际的名将，斩他将会对我大吴造成难以弥补的损失。"},{"type":"say","who":"孙綝","text":"笑话，我就不相信一个小小朱异能有多了不起。"},{"type":"say","who":"丁封","text":"镇南将军，您也向大将军道歉认错吧。"},{"type":"say","who":"朱异","text":"我没有错，为什么要认！"},{"type":"say","who":"孙綝","text":"快！给我砍了他！士兵"},{"type":"say","who":"旁白","text":"▶ 是！"},{"type":"say","who":"朱异","text":"孙綝，你这个无能又残暴的蠢猪，我在那边等著看你被诛杀的一天。"},{"type":"say","who":"陆抗","text":"（我本来以为孙綝这家伙不管再怎么残忍，终究只会杀北方人或是孙家亲族。）"},{"type":"say","who":"陆抗","text":"（过去孙峻看我们江东士族已经退居二线，因为没有威胁性，所以从来没有杀过任何一人。）"},{"type":"say","who":"陆抗","text":"（然而这次居然把吴四姓中，最具有代表的朱家当家给杀了，这就表示他的屠刀也将对向我们，我们不能再冷眼旁观。）东吴镇南将军朱异，以部下饥饿，没有战斗力为由，拒绝孙綝的出兵命令。没想到，孙綝居然当场斩杀朱异。不久后，孙綝率领大军返回建业。因为他既不能救出诸葛诞，又丧师辱国，诛杀名将，全国上下，开始怨恨孙綝。胜败的分歧寿春魏军营帐"},{"type":"say","who":"司马昭","text":"好好好，仲容的表现真令我大开眼界，能以少数精兵打败吴贼的精锐部队。"},{"type":"say","who":"司马昭","text":"这次你辛苦了，你想要什么赏赐？"},{"type":"say","who":"石苞","text":"十个美女就够！"},{"type":"say","who":"州泰","text":"你…你怎么这么丢人！还说得这么理直气壮！"},{"type":"say","who":"陈骞","text":"哼，没出息。"},{"type":"say","who":"州泰","text":"你看！被人家鄙视了吧。"},{"type":"say","who":"石苞","text":"哼，你们这些伪君子，我就不相信你们不想要美女。"},{"type":"say","who":"陈骞","text":"（如果是我，我想要二十个。）"},{"type":"say","who":"司马昭","text":"朱异不能挺进到寿春，孙綝把他杀掉，其实这并不是朱异的过错。"},{"type":"say","who":"司马昭","text":"其实这是孙綝为了要向寿春表示歉意，坚定诸葛诞意志，使他希望不至于破灭。"},{"type":"say","who":"司马昭","text":"我们现在更要加强包围网，防备他们突围，要用谋略，来使他们做出错误决定。"},{"type":"say","who":"钟会","text":"我建议散布谣言，来消耗敌人的粮食。"},{"type":"say","who":"钟会","text":"就说东吴援军即将抵达，围城大军粮秣不继，已经把部分军队送到淮河以北的郡县，马上就要解围。"},{"type":"say","who":"司马昭","text":"公主，你看如何？"},{"type":"say","who":"裴秀","text":"我以为这样的谣言起不了任何作用，难道贼人不会去查明真伪？"},{"type":"say","who":"钟会","text":"（这个裴秀真碍眼，你是卯足劲要和我斗下去？）"},{"type":"say","who":"裴秀","text":"（钟会，像你这样的恶人不配为司马公效命。）"},{"type":"say","who":"曹绫","text":"我想，诸葛诞应该会相信这样的谣言，对于城中的粮食消耗不加以控管，不出半个月，寿春城一定缺粮。"},{"type":"say","who":"司马昭","text":"哦？但万一敌人因此集中兵力想要突围，我军又该怎么办？"},{"type":"say","who":"曹绫","text":"敌人现在不可能突围的，因为现在城中人多口杂，在号令不统一的情况下，没有人能够统整兵力来突围。"},{"type":"say","who":"司马昭","text":"我倒是认为，敌人或许还在等我军后方有发生变故喔…"},{"type":"say","who":"曹绫","text":"现在我大魏还能发生什么样的变故？"},{"type":"say","who":"司马昭","text":"是呀，毕竟可能制造变故的人，现在都已经坐在我营帐中了。"},{"type":"say","who":"陈泰","text":"………"},{"type":"say","who":"曹绫","text":"………缓缓围城发动最猛烈攻击"},{"type":"say","who":"司马昭","text":"我们就慢慢围著寿春，等他们粮尽力殆的时候再来收拾他们。"},{"type":"say","who":"司马昭","text":"全军准备对寿春城发动最猛烈的攻击，务求将诸葛诞、文钦和吴贼歼灭于寿春。争论寿春议事厅"},{"type":"say","who":"诸葛诞","text":"居然中了司马昭的诡计，这下本来应该充沛的粮食，现在居然开始短缺了。"},{"type":"say","who":"文钦","text":"早就说过要你注意粮食的消耗，偏偏你就"},{"type":"say","who":"旁白","text":"▶ 是不听。"},{"type":"say","who":"诸葛诞","text":"现在说这些有什么用，应该想想接下来的对策。"},{"type":"say","who":"文钦","text":"现在敌人大军正在外面筑防御工事要包围我们，我建议应该立刻趁工事未完成前发动攻击。"},{"type":"say","who":"文钦","text":"否则包围之势形成，外面的援军也很难再进入了。"},{"type":"say","who":"诸葛诞","text":"哈哈哈，仲若呀，毕竟你待在淮南的时间没有我久，不知道淮南这里的气候。"},{"type":"say","who":"诸葛诞","text":"寿春每年都会下大雨，淮河会暴涨淹没城邑。"},{"type":"say","who":"诸葛诞","text":"司马昭不知道这点，把部队集结在随时会氾滥的地方，不用我们出手，他们马上就会变成虾兵蟹将了。"},{"type":"say","who":"诸葛诞","text":"到时候会合城外东吴军队，何愁大事不成？"},{"type":"say","who":"蒋班","text":"我认为朱异大军不能前进，孙綝诛杀他而回军。虽然嘴巴说将集结大军，实际上早就无能为力，只是眼巴巴看我们战败。"},{"type":"say","who":"焦彝","text":"现在我军士气还算旺，军心也坚定，应该抓住机会攻击敌人单一据点，虽然不能大获全胜，但总会有人突围而出。"},{"type":"say","who":"焦彝","text":"呆坐在这边等死，没有任何意义。"},{"type":"say","who":"文钦","text":"我反对！"},{"type":"say","who":"文钦","text":"你率领十几万大军，归附大吴。我和全怿等都陪你陷在必死之地，父母子女也都在江表。"},{"type":"say","who":"文钦","text":"今天纵然孙綝不打算援救，圣上和全怿等将士的亲戚又岂能接受？"},{"type":"say","who":"诸葛诞","text":"（说得也是，现在城中的全家班，都是东吴最有权势的一群人，我想就算孙綝不理我们，全公主也不会坐视不管。）"},{"type":"say","who":"文钦","text":"何况中原没有一年不发生巨变，军民辛劳疲惫。我们再守一年，他们内部形势必定会发生变化，为什么要去冒这个险呢？"},{"type":"say","who":"文钦","text":"（想当初我没有听尹大目的话，错失了反攻的良机，这次怎么能够重蹈上次的覆辙呢？）"},{"type":"say","who":"蒋班","text":"那是馊主意啊！"},{"type":"say","who":"焦彝","text":"如果现在不突围，等到以后我军没有战力时再突围，就来不及了。"},{"type":"say","who":"蒋班","text":"不然…您可以把诸葛姑娘请来，问问她的意见如何？"},{"type":"say","who":"诸葛诞","text":"够了！这种事情又不是她可以决定的，你们再啰唆，我保证你们人头落地。"},{"type":"say","who":"蒋班","text":"这……"},{"type":"say","who":"焦彝","text":"（别再说了，你看看诸葛将军的眼神，那可是真的带有杀意的眼神。）诸葛诞对于蒋班和焦彝的坚持己见感到愤怒和猜忌，打算诛杀两人。蒋班和焦彝感到恐惧，翻墙出城，投奔曹魏围城军。名士诸葛诞寿春诸葛府"},{"type":"say","who":"诸葛诞","text":"有件事情可以请教一下吗？"},{"type":"say","who":"诸葛果","text":"什么事情？"},{"type":"say","who":"诸葛诞","text":"你这次前来的真正目的。"},{"type":"say","who":"诸葛诞","text":"听说蜀地大将军姜维在上邽附近受挫，损失幅度不小，兵力衰弱到连防御我大魏的入侵都有问题。"},{"type":"say","who":"诸葛诞","text":"我左思右想你特地从蜀地前来的原因，就是说动我起兵，让蜀地有喘息的时间。"},{"type":"say","who":"诸葛果","text":"族叔说的完全正确。"},{"type":"say","who":"诸葛果","text":"果在主公最需要我的时候病倒，导致主公面对邓艾的时候孤立无援，因此我必须要为主公做些什么。"},{"type":"say","who":"诸葛诞","text":"果然如此，我真是太小看你，同样也太小看族兄那支诸葛分家的厉害。"},{"type":"say","who":"诸葛果","text":"不过族叔怎么想？如果感觉是被果骗，那么就请即刻诛杀我。"},{"type":"say","who":"诸葛诞","text":"呵呵，我被骗了十多年，难得有人肯对我说真话，我又怎么可能杀说真话的人。"},{"type":"say","who":"诸葛诞","text":"更何况，如果没有你推我一把，我怎么可能回想起自己是正始名士的事情。"},{"type":"say","who":"诸葛诞","text":"只是，不瞒你说…想起要和我一手让它壮大的司马家为敌，我可是害怕得不得了。"},{"type":"say","who":"诸葛诞","text":"我没毌丘仲恭的勇气，完全没有胆量和司马昭麾下的精兵悍将对决，只敢躲在寿春城抵抗。"},{"type":"say","who":"诸葛果","text":"毌丘俭是毌丘俭，你是你，既然你能下定决心对抗司马家，就已经是难能可贵了。"},{"type":"say","who":"诸葛诞","text":"我实在是很难想像后世会怎么评价我？是大魏的忠臣？还是愚蠢的叛贼？"},{"type":"say","who":"诸葛诞","text":"只是可怜我的家人，恐怕都要跟著陪葬。或许以后，琅邪诸葛家就只剩你们蜀地的这支了。"},{"type":"say","who":"诸葛果","text":"不，你忘记你的女婿是司马家的人？还有因为毌丘俭叛乱后修改的法律？"},{"type":"say","who":"诸葛诞","text":"你真的是怪物，怎么会连我大魏的事情都知道得这么清楚。"},{"type":"say","who":"诸葛诞","text":"说得也是，小女很可能会因为嫁给司马槺而逃过一劫，而且司马家还有混著我诸葛家的血统…哼，哈哈哈哈哈…"},{"type":"say","who":"诸葛诞","text":"看来这场仗，我不管怎么样都会是赢家…"},{"type":"say","who":"诸葛果","text":"就让果陪你到最后吧。"},{"type":"say","who":"诸葛诞","text":"我怎么能害你跟我一起死？想办法活下去，以你的聪明才智，一定可以找到活路。"},{"type":"say","who":"诸葛诞","text":"（这个诸葛果对我坦白，应该可以信任，但是其他人呢？文钦可以信任？东吴将领可以信任？）奇兵的行动寿春附近"},{"type":"say","who":"陆抗","text":"再往前走就是贼营的包围网，你确定你要跟过来？"},{"type":"say","who":"甘宁","text":"你能离得开我？没有我，你应该什么都做不成吧。"},{"type":"say","who":"陆抗","text":"很抱歉，因为我的独断独行，把你给拖下水了。"},{"type":"say","who":"甘宁","text":"孙綝这家伙为了一己之私，宁愿把三万大吴军队丢下都要回军。"},{"type":"say","who":"甘宁","text":"他制造的怨恨早晚会把他吞掉，一年内就可以预见他的败亡。"},{"type":"say","who":"陆抗","text":"就因为这样，所以我才想要多拯救点这些被围困的将士，就算只救到一个也好。"},{"type":"say","who":"甘宁","text":"不只这样吧…诸葛靓的那封信似乎也对你影响不小，是牵动你对陆逊的感情吧。"},{"type":"say","who":"陆抗","text":"十年前，我看著爹被小人围攻，却没有办法帮他一点忙，我是眼睁睁看著他被人害死。"},{"type":"say","who":"陆抗","text":"现在我却有这个能力去帮忙拯救别人的父亲，如果我不做，就是再度犯下当时的错误。"},{"type":"say","who":"甘宁","text":"你想太多了，陆逊的情况不是你可以挽回的，同样援救诸葛诞也不是你能力所及。"},{"type":"say","who":"陆抗","text":"为什么你说话总是这么不留情？"},{"type":"say","who":"甘宁","text":"不过我不讨厌像你这样的人，所以我才会帮你。"},{"type":"say","who":"甘宁","text":"更何况，如果我的预感没有错，那个疯子恐怕会有惊人的举动。"},{"type":"say","who":"陆抗","text":"疯子？你是说文俶？"},{"type":"say","who":"甘宁","text":"除了他，还有谁呢？这几年来，他对我挑衅了无数次，你知道这代表什么？"},{"type":"say","who":"陆抗","text":"他是个连自己人都不放过的疯子？"},{"type":"say","who":"甘宁","text":"对，这种人没有什么原则，千万别把一般人的价值观套到他身上。赵家受辱寿春防卫军军营"},{"type":"say","who":"赵统","text":"弟弟快离远一点，这家伙强得跟怪物一样。"},{"type":"say","who":"文鸯","text":"就这种水准？你的动作慢到苍蝇都可以停在身上了。"},{"type":"say","who":"文鸯","text":"这才是真正的速度！"},{"type":"say","who":"赵广","text":"不见了？"},{"type":"say","who":"赵统","text":"什么？"},{"type":"say","who":"文鸯","text":"太慢了！"},{"type":"say","who":"赵统","text":"啊！"},{"type":"say","who":"文鸯","text":"你真的是赵云的儿子？我曾经听说赵云有万夫不当之勇，结果你却被我一击打倒。"},{"type":"say","who":"赵统","text":"可恶…完全不能动弹…"},{"type":"say","who":"赵广","text":"你突然攻击我大哥，让我大哥来不及防备，难道就公道？"},{"type":"say","who":"文鸯","text":"不服气的话，你也攻过来呀。"},{"type":"say","who":"赵统","text":"不要…这家伙合我们兄弟之力都不是对手。"},{"type":"say","who":"文鸯","text":"不应该是这样的…不应该是这样的…"},{"type":"say","who":"文鸯","text":"我真恨我晚生了五十年，不能和那些强悍的武将一较高下。"},{"type":"say","who":"文鸯","text":"到现在我只碰过一个让我觉得惊艳的武将，只是在我在东吴这段期间，她一直拒绝和我交手。"},{"type":"say","who":"文鸯","text":"本来以为你这个赵云之子可以让我惊喜一下，没想到终究是让我失望。"},{"type":"say","who":"赵广","text":"你别得意，我们赵家的武艺，绝对不只如此而已。"},{"type":"say","who":"文鸯","text":"你比起你兄长更是可悲，你兄长虽然不敌，但还表现出武将的气魄，但是你呢？你只是躲在旁边发抖而已。"},{"type":"say","who":"赵统","text":"（连他什么时候挥剑的都不知道，这家伙也太可怕了。）"},{"type":"say","who":"赵统","text":"（可恶，为什么我会这么不堪一击，难道我的实力真的只有这样？）"},{"type":"say","who":"赵统","text":"（人家关家和张家后人都有表现，而我赵统却害父亲被人嘲笑…）"},{"type":"say","who":"赵广","text":"（面对真正的高手，我居然连挺身而对的勇气都没有，我真是丢父亲的脸。）吴将的志气寿春议事厅"},{"type":"say","who":"文钦","text":"防务大概都安置妥当了，我想面对敌军攻击，应该也可以挡得住。"},{"type":"say","who":"唐咨","text":"有件事情我想问问，镇北大将军您真的愿意和诸葛诞合作？"},{"type":"say","who":"文钦","text":"我比谁都讨厌诸葛诞，当年如不是诸葛诞在后面阻挠，我和仲恭恐怕早就可以打败司马师了。"},{"type":"say","who":"唐咨","text":"那么您有什么理由为他卖命？"},{"type":"say","who":"文钦","text":"为了大义，我战死于此也在所不惜。"},{"type":"say","who":"唐咨","text":"大义值多少钱？您要知道，城中有三万大吴军队被困在这里，要是城破，大家都没有生还机会。"},{"type":"say","who":"唐咨","text":"您是出身名门，可以有谯县文家的骄傲。但我不是，我唐咨是从烂泥堆中打滚出来的，我只求存活就好。"},{"type":"say","who":"文钦","text":"我记得你当年慷慨激昂，在利城起兵反抗文帝，怎么现在没有当年的勇气？"},{"type":"say","who":"唐咨","text":"那时我一个人漂流到大吴，靠著军功爬到高位，享受了过去从没有享受过的荣华富贵。"},{"type":"say","who":"唐咨","text":"我终于想通了，什么壮烈牺牲都是鬼扯，只有保全自己性命才是最重要的事情。"},{"type":"say","who":"文钦","text":"你说的我也明白，仲恭也对我这样说过。"},{"type":"say","who":"文钦","text":"但是，我已经厌烦这样的生活了，我不想再回去东吴过著寄人篱下的日子，我想要在这里光荣地结束自己的生命。"},{"type":"say","who":"唐咨","text":"那么您的儿子们呢？他们年轻的生命就该这样消失？"},{"type":"say","who":"文钦","text":"这也是无可奈何的事情，他们也都愿意为这样的大义而死，不是吗？"},{"type":"say","who":"唐咨","text":"真是自私呀！"},{"type":"say","who":"于诠","text":"我已经多久没有听过这样慷慨激昂的发言，为什么我大吴已经没有这样的武将？"},{"type":"say","who":"于诠","text":"这几年来，我每天看著应该是自己人的武将大臣在那互相砍杀，却无一人愿意和外敌交战牺牲。"},{"type":"say","who":"于诠","text":"我神往过去长沙桓王平定江东的威武，也赞叹周郎以寡击众的气魄，曾几何时，我大吴居然变成充斥著偷生者的国度。"},{"type":"say","who":"于诠","text":"镇北大将军，我的性命就交给您了，就算死，也要死得像是个武将。"},{"type":"say","who":"唐咨","text":"真是一窝笨蛋，好吧，我也陪你们到最后一刻了。"},{"type":"say","who":"文钦","text":"实在是不胜感激。"},{"type":"say","who":"唐咨","text":"倒是…全家那群人跑哪去了？为什么这个重要时刻会看不到全家人？摆荡的忠义寿春议事厅"},{"type":"say","who":"诸葛诞","text":"从司马昭军队的动向来看，似乎准备要对寿春发动总攻击了。"},{"type":"say","who":"诸葛诞","text":"我们就用寿春坚固的城墙，来让司马昭大军都葬身于此。"},{"type":"say","who":"文钦","text":"都是你的馊主意，什么淮河一定暴涨，你看现在一滴雨都没下。"},{"type":"say","who":"文钦","text":"结果我们眼睁睁看著敌人把寿春围得跟铁桶一样，全都是你害的。"},{"type":"say","who":"诸葛诞","text":"怪我了？！我怎么知道今年寿春会突然遭逢大旱？"},{"type":"say","who":"文钦","text":"算了，面对敌人的攻击，我军也该派人在城外游击，守住城外的据点。"},{"type":"say","who":"诸葛诞","text":"你认为该派谁去守？这可是非常危险的任务。"},{"type":"say","who":"文钦","text":"就让我的两个儿子去，相信你也见过当时在乐嘉之战之中阿鸯的表现了吧。"},{"type":"say","who":"诸葛诞","text":"（不对劲，难道文家兄弟是想先在城外投降司马昭，然后再和文钦在城内来个里应外合？）"},{"type":"say","who":"文钦","text":"到了这个时候，你还在猜忌吗？！你认为我文钦会投降司马昭？司马师的性命记在我们父子名下，我们怎么可能投降他？"},{"type":"say","who":"诸葛诞","text":"不，我没有这个意思。"},{"type":"say","who":"于诠","text":"我可以保证文将军的忠诚，我们大吴军队也都决定要在这里和寿春共存亡了！"},{"type":"say","who":"唐咨","text":"我或许是数姓家奴，但这次，我想好好打场漂亮的仗！"},{"type":"say","who":"文鸯","text":"就让我顺手摘下小昭昭的脑袋吧，我等这一刻已经很久了。"},{"type":"say","who":"诸葛诞","text":"（诸葛果为什么不说一句话，还有这对赵家兄弟，如果他们开口的话，我可以随时派他们接替文家父子。）"},{"type":"say","who":"文鸯","text":"赵家兄弟是绝对无法担当这个重任的，昨天我已经试过他们的实力了。"},{"type":"say","who":"赵统","text":"………"},{"type":"say","who":"赵广","text":"………"},{"type":"say","who":"诸葛诞","text":"好吧，寿春小城的守备工作就劳烦你了。"},{"type":"say","who":"诸葛诞","text":"成功失败，就在这一刻，我们要守住寿春，让司马家知道正义是站在哪一方！"},{"type":"say","who":"文钦","text":"（正义是你这种人可以说的？）產ち传"},{"type":"say","who":"诸葛诞","text":"出发，打倒司马昭！產ち传"},{"type":"say","who":"诸葛诞","text":"我想问你，现在的我…是否稍微接近族兄一些了？"},{"type":"say","who":"诸葛果","text":"功绩上或许略有不及，但是精神上已经相当接近了。"},{"type":"say","who":"诸葛诞","text":"如果是你说的，应该是真的吧。"},{"type":"say","who":"诸葛诞","text":"我很崇拜族兄，虽然是敌对阵营，但是他的《出师表》和《正议》都看得我感动不已，这样的人，实在是我的榜样。產ち传"},{"type":"say","who":"赵统","text":"（我不甘心，虽说我武艺和天份都不及父亲，但也不应该会面对文鸯到毫无招架之力。）產ち传"},{"type":"say","who":"赵广","text":"（为什么我会变得这么胆怯，过去我在战场上，不管面对实力多强的对手，不都应该挺身面对吗？）"},{"type":"say","who":"赵广","text":"（这样下去，我怎么能面对当年命丧我手的魏家兄弟呢？）產ち传"},{"type":"say","who":"诸葛诞","text":"希望我们这次可以携手合作，打倒司马昭，回复大魏的秩序。"},{"type":"say","who":"文钦","text":"我虽然很讨厌你，但是现在也只有和你合作，才有帮昭伯和仲恭报仇的可能。"},{"type":"say","who":"诸葛诞","text":"（你这家伙眼中就永远没有我？曹爽优柔寡断，咎由自取。毌丘俭抱著不切实际的空想送死，我哪点比不上那群笨蛋？）"},{"type":"say","who":"文钦","text":"（诸葛诞，你还是不明白你和那些人的差距？他们都是可以为理想而死的英雄，而你却永远在理想与现实的中间摆荡。）產ち传"},{"type":"say","who":"文鸯","text":"上次司马师麾下没有让人感到印象深刻的将领，这次司马昭会不会让我失望？"},{"type":"say","who":"文鸯","text":"司马昭，你看见你自己的死兆星了吗？產ち传"},{"type":"say","who":"唐咨","text":"这场仗，我是决定要打到底了！就像当年挺身对抗曹贼的暴政一样。產ち传"},{"type":"say","who":"于诠","text":"这场战斗，就算拚上我的性命，也要让大吴军队的名声，在这场战斗中彰显！產ち传"},{"type":"say","who":"全怿","text":"（全辉和全仪这两个混蛋居然给我投奔敌营，现在我回到大吴，恐怕也很难说不会被追究。）"},{"type":"say","who":"全怿","text":"（更危险的是，本来以为孙綝不会对我们江东士族动刀，但是自从朱异被杀之后，我也很难相信他不动我们钱塘全家。）"},{"type":"say","who":"全怿","text":"（现在我到底该怎么办呢？）"},{"type":"battle","index":0}]},"battles":[{"index":0,"width":16,"height":10,"objective":"全灭敌军","grid":["ffffffffffffffff","ffffffffffffffff","ffppppppppppppff","fppppppppppppppf","fpwwwpppppwwwppf","fpwwpppppppwwppf","fpwwwpppppwwwppf","fppppppppppppppf","ffppppppppppppff","ffffffffffffffff"],"units":[{"def":{"name":"姜维","class":"commander","level":8,"skills":["fireball","heal","inspire"],"weapon":"sword","leader":true},"x":3,"y":4,"faction":"ally"},{"def":{"name":"赵云","class":"hero","level":9,"skills":["charge"],"weapon":"hualiu"},"x":4,"y":5,"faction":"ally"},{"def":{"name":"王平","class":"infantry","level":7,"skills":[],"weapon":"sword"},"x":3,"y":6,"faction":"ally"},{"def":{"name":"马岱","class":"dragoon","level":7,"skills":["charge"],"weapon":"halberd"},"x":5,"y":5,"faction":"ally"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":3,"faction":"enemy"},{"def":{"name":"魏将","class":"officer","level":6,"skills":[],"weapon":"sword"},"x":11,"y":7,"faction":"enemy"},{"def":{"name":"枪兵","class":"spearman","level":5,"skills":[],"weapon":"spear"},"x":10,"y":5,"faction":"enemy"},{"def":{"name":"弓兵","class":"archer","level":5,"skills":[],"weapon":"bow"},"x":13,"y":4,"faction":"enemy"}]}]});
})();
